(window.STORIES=window.STORIES||[]).push(
{"id": 1031, "siri": "Sirah-02", "no": 1, "nama": "Mus'ab bin Umair", "tajuk": "Saidina Mus'ab bin Umair RA — Duta Pertama Yang Mengubah Madinah Dengan Al-Quran", "lokasi": "Zulhijjah Tahun 12 Kenabian (621 M) | Sebelum Hijrah Ke Madinah", "subtema": "Muhajirin / Duta Ansar", "ibrah": "Komunikasi Berhikmah, Ilmu & Kepimpinan Muda", "sumber": "Sahih Al-Bukhari 3925", "link": "https://sunnah.com/bukhari:3925", "tema": "Ilmu & Dakwah", "hook": "Bagaimana seorang pemuda berumur 20-an yang datang ke sebuah kota asing tanpa sebarang tentera dan senjata mampu membuka hati ribuan penduduk kota itu menerima Islam dalam masa setahun sahaja?", "body": ["Itulah kehebatan luar biasa duta pertama dalam sejarah Islam, Saidina Mus'ab bin Umair RA.", "Di dalam Sahih Al-Bukhari, sahabat Ansar Al-Bara' bin 'Azib RA menceritakan:", "\"Orang pertama yang tiba kepada kami di Madinah ialah Mus'ab bin Umair dan Ibn Umm Maktum, yang bertugas mengajarkan Al-Quran kepada orang ramai.\"", "Selepas termeterainya Bai'ah Aqabah Pertama, 12 orang wakil dari Yathrib (Madinah) memohon kepada Rasulullah S.A.W. agar mengutuskan seorang guru untuk membimbing kaum mereka.", "Rasulullah S.A.W. tidak memilih orang tua yang keras, sebaliknya memilih pemuda yang paling santun tutur katanya, paling tajam ilmunya, dan paling mulia akhlaknya: Mus'ab bin Umair RA.", "Di Madinah, Mus'ab RA menumpang di rumah tokoh Ansar, As'ad bin Zurarah RA.", "Suatu hari, dua orang ketua besar kabilah Aws iaitu Usaid bin Hudhair dan Sa'ad bin Mu'adh datang dengan wajah bengis sambil memegang tombak untuk menghalau Mus'ab RA.", "Adakah Mus'ab RA panik atau melawan dengan kata-kata kasar?", "Langsung tidak!", "Dengan wajah tenang dan penuh adab, Mus'ab RA berkata:", "\"Tidakkah tuan sudi duduk sejenak dan mendengar apa yang aku sampaikan? Sekiranya tuan menyukainya, tuan boleh menerimanya; dan jika tuan membencinya, kami akan berhenti dan pergi.\"", "Kata-kata yang penuh hormat itu meruntuhkan ego kedua-dua ketua kabilah tersebut.", "Sebaik sahaja Mus'ab RA membacakan permulaan Surah Az-Zukhruf dengan suaranya yang merdu, hati Usaid dan Sa'ad bin Mu'adh terus tersentuh lalu memeluk Islam, sekali gus menyebabkan seluruh kabilah Bani Abdil Asyhal masuk Islam pada petang yang sama!", "3 Pengajaran (Ibrah) Untuk Kita:", "Kelembutan Bahasa Meruntuhkan Ego Manusia: Hujah yang paling bernas sekalipun akan ditolak jika disampaikan dengan sombong, tetapi komunikasi yang tenang dan menghormati pendengar mampu membuka hati yang keras.", "Kepercayaan Kepada Potensi Orang Muda: Rasulullah S.A.W. menyerahkan misi diplomatik paling kritikal di Madinah kepada seorang pemuda kerana kematangan ilmu dan akhlaknya.", "Ilmu Al-Quran Adalah Asas Pembinaan Masyarakat: Sebelum membina kekuatan politik atau ekonomi di Madinah, asas pertama yang ditanam oleh Mus'ab RA di setiap rumah kaum Ansar ialah kefahaman Al-Quran.", "Apabila kita berdepan dengan orang yang tidak bersetuju dengan kita hari ini, adakah kita membalas dengan emosi atau menyantuni mereka dengan hikmah seperti Mus'ab bin Umair RA?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1032, "siri": "Sirah-02", "no": 2, "nama": "Mus'ab bin Umair", "tajuk": "Saidina Mus'ab bin Umair RA — Pemuda Paling Mewah Yang Syahid Dengan Sehelai Kain Singkat", "lokasi": "7 Syawal 3 Hijrah (Mac 625 M) | Perang Uhud, Madinah", "subtema": "Muhajirin", "ibrah": "Pengorbanan Kemewahan, Keikhlasan & Nilai Akhirat", "sumber": "Sahih Al-Bukhari 1276", "link": "https://sunnah.com/bukhari:1276", "tema": "Kepimpinan & Keberanian", "hook": "Dahulunya beliau adalah pemuda paling kacak dan paling mewah di kota Makkah, namun ketika gugur syahid di medan Uhud, tiada sehelai kain pun yang cukup panjang untuk menutup seluruh jasadnya!", "body": ["Kisah yang meruntun jiwa Rasulullah S.A.W. dan seluruh sahabat ini direkodkan secara sahih oleh Imam Al-Bukhari menerusi kesaksian Khabbab bin Al-Aratt RA.", "Sebelum memeluk Islam, Mus'ab bin Umair RA merupakan anak emas keluarganya yang kaya-raya.", "Pakaiannya ditempah khas daripada sutera dan kain terbaik dari Yaman, manakala minyak wanginya yang paling mahal dapat dihidu dari jauh setiap kali beliau melalui lorong-lorong Makkah.", "Namun apabila cahaya iman menyapa hatinya, ibunya menghentikan segala kemewahan dan mengurungnya supaya beliau meninggalkan Islam.", "Mus'ab RA memilih untuk meninggalkan segala harta dunia itu demi Allah dan Rasul-Nya, sehingga kulitnya yang dahulunya halus menjadi kasar dan pakaiannya bertampal-tampal.", "Pada hari Perang Uhud, Mus'ab RA diamanahkan memegang panji utama tentera Islam.", "Beliau mempertahankan Rasulullah S.A.W. habis-habisan sehingga kedua-dua belah tangannya ditebas musuh, namun beliau tetap mengepit panji Islam di dadanya sehingga gugur syahid terkena tusukan tombak.", "Selepas pertempuran tamat, Khabbab bin Al-Aratt RA menceritakan di dalam Sahih Al-Bukhari:", "\"Mus'ab bin Umair telah gugur syahid pada hari Perang Uhud, dan kami tidak menemui sebarang kain untuk mengkafankannya melainkan sehelai kain Burdah (kain kasar bergaris) miliknya. Apabila kami menutup bahagian kepalanya dengan kain itu, maka terbukalah kedua-dua belah kakinya; dan apabila kami menutup kakinya, maka terbukalah pula kepalanya!\"", "Melihat keadaan yang menyayat hati itu, Rasulullah S.A.W. bersabda dengan penuh hiba:", "\"Tutuplah bahagian kepalanya dengan kain itu, dan tutuplah bahagian kakinya dengan rumput Idzkhir (rumput wangi Makkah/Madinah).\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Nilai Manusia Bukan Pada Jenama Pakaian: Mus'ab RA meninggalkan pakaian paling mahal di dunia kerana beliau sedar kemuliaan abadi di sisi Allah jauh lebih berharga daripada kemewahan sementara.", "Keikhlasan Yang Terpelihara Daripada Balasan Dunia: Khabbab RA menyatakan bahawa Mus'ab RA pergi menghadap Allah dalam keadaan pahala pengorbanannya masih utuh 100% tanpa sedikit pun diambil balasannya di dunia.", "Pegangan Prinsip Sehingga Nafas Terakhir: Walaupun kehilangan kedua-dua tangan di medan Uhud, Mus'ab RA tidak membiarkan panji amanah jatuh ke tanah selagi nyawa masih di kerongkong.", "Adakah kita terlalu mengejar kemewahan dunia sehingga terlupa menyiapkan bekalan yang bakal menemani kita di alam kubur kelak?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1033, "siri": "Sirah-02", "no": 3, "nama": "Sa'ad bin Mu'adh", "tajuk": "Saidina Sa'ad bin Mu'adh RA — Enam Tahun Dalam Islam, Namun Arasy Allah Bergegar", "lokasi": "Zulkaedah 5 Hijrah (Mac 627 M) | Kewafatan Ketua Kaum Ansar Di Madinah", "subtema": "Ketua Ansar (Aws)", "ibrah": "Kualiti Amal Melebihi Tempoh Masa & Kesetiaan", "sumber": "Sahih Al-Bukhari 3803", "link": "https://sunnah.com/bukhari:3803", "tema": "Akhlak & Adab", "hook": "Beliau memeluk Islam pada usia 30 tahun dan wafat pada usia 36 tahun — hanya enam tahun sahaja sempat hidup sebagai seorang Muslim, tetapi kematiannya membuatkan Arasy Allah Yang Maha Pemurah bergegar!", "body": ["Kisah kemuliaan ketua kaum Ansar (kabilah Aws), Saidina Sa'ad bin Mu'adh RA ini direkodkan secara mutawatir di dalam Sahih Al-Bukhari dan Sahih Muslim.", "Ramai orang menyangka untuk mencapai darjat tertinggi di sisi Allah, seseorang memerlukan tempoh ibadah selama berpuluh-puluh tahun.", "Namun Sa'ad bin Mu'adh RA membuktikan bahawa nilai di sisi Allah bergantung kepada keikhlasan dan kualiti pengorbanan, bukan semata-mata panjangnya usia!", "Sejak hari pertama beliau mengucap syahadah di tangan Mus'ab bin Umair RA, Sa'ad bin Mu'adh RA menyerahkan seluruh pengaruh, harta, dan nyawanya untuk melindungi Rasulullah S.A.W.", "Ketika Perang Badr dan Perang Uhud, beliaulah yang berdiri teguh menyatakan kesediaan kaum Ansar meredah lautan bersama Baginda S.A.W.", "Semasa Perang Ahzab (Khandaq) pada tahun ke-5 Hijrah, sebatang anak panah musuh mengenai urat lengan Sa'ad RA (al-akhal).", "Luka tersebut akhirnya membawa kepada kewafatan beliau selepas selesainya urusan Bani Quraizah.", "Ketika jenazah Sa'ad bin Mu'adh RA diusung, Jabir bin Abdullah RA meriwayatkan bahawa Rasulullah S.A.W. bersabda:", "\"Telah bergegar Arasy Tuhan Yang Maha Pemurah (Ar-Rahman) kerana kematian Sa'ad bin Mu'adh!\"", "Para ulama menjelaskan bahawa gegaran Arasy itu adalah tanda kegembiraan dan sambutan agung penduduk langit terhadap ketibaan roh Sa'ad bin Mu'adh RA yang begitu tulus mencintai Allah dan Rasul-Nya!", "3 Pengajaran (Ibrah) Untuk Kita:", "Kualiti Amal Mengatasi Kuantiti Usia: Enam tahun kehidupan yang dipenuhi keikhlasan dan khidmat sepenuh jiwa kepada agama mampu mengangkat seseorang ke maqam yang menggegarkan langit.", "Gunakan Kedudukan Untuk Membela Kebenaran: Sebagai ketua kabilah Aws, Sa'ad RA menggunakan pengaruh kepimpinannya untuk mengajak seluruh kaumnya beriman dan melindungi Rasulullah S.A.W.", "Kematian Orang Soleh Dirindui Oleh Penduduk Langit: Apabila seorang mukmin hidup dengan penuh ketaatan, saat kematiannya bukanlah satu tragedi, tetapi detik pertemuan yang diraikan oleh malaikat dan Pencipta.", "Jika usia kita yang berbaki ini hanya tinggal beberapa tahun sahaja lagi, apakah sumbangan terbaik yang mahu kita tinggalkan untuk agama?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1034, "siri": "Sirah-02", "no": 4, "nama": "Sa'ad bin Mu'adh", "tajuk": "Saidina Sa'ad bin Mu'adh RA — Sapu Tangannya Di Syurga Lebih Indah Daripada Sutera Raja", "lokasi": "Fasa Madinah | Kemuliaan Ganjaran Syurga Buat Sa'ad bin Mu'adh RA", "subtema": "Ketua Ansar (Aws)", "ibrah": "Nilai Ganjaran Syurga vs Perhiasan Sementara Dunia", "sumber": "Sahih Al-Bukhari 3802", "link": "https://sunnah.com/bukhari:3802", "tema": "Akhlak & Adab", "hook": "Para sahabat sedang terpegun menyentuh kehalusan sehelai jubah sutera bersulam emas hadiah seorang pembesar dunia, namun Rasulullah S.A.W. memberitahu bahawa kain sapu tangan Sa'ad bin Mu'adh di Syurga jauh lebih indah daripada sutera itu!", "body": ["Kisah sahih yang membuka mata kita tentang perbandingan nilai dunia dan akhirat ini diriwayatkan oleh Al-Bara' bin 'Azib RA di dalam Sahih Al-Bukhari.", "Pada suatu hari, sehelai kain atau pakaian sutera yang sangat halus dan mewah dihadiahkan kepada Rasulullah S.A.W.", "Para sahabat yang hadir di majlis tersebut mula menyentuh kain sutera itu seorang demi seorang.", "Mereka berasa kagum kerana belum pernah melihat atau memegang kain yang begitu lembut dan indah buatannya.", "Melihat kekaguman para sahabat terhadap perhiasan dunia itu, Rasulullah S.A.W. bertanya kepada mereka:", "\"Adakah kamu semua berasa kagum dengan kelembutan dan kehalusan kain sutera ini?\"", "Para sahabat menjawab, \"Ya, wahai Rasulullah, kami belum pernah melihat kain yang lebih baik dan lebih lembut daripada ini.\"", "Lalu Rasulullah S.A.W. bersabda:", "\"Sesungguhnya sapu tangan-sapu tangan (manadil) milik Sa'ad bin Mu'adh di dalam Syurga adalah jauh lebih baik dan lebih lembut daripada kain sutera ini!\"", "Bayangkan, kain sapu tangan yang digunakan sekadar untuk mengelap tangan milik Sa'ad bin Mu'adh RA di dalam Syurga sahaja sudah mengatasi pakaian sutera paling mewah milik raja-raja di dunia!", "3 Pengajaran (Ibrah) Untuk Kita:", "Jangan Terpukau Dengan Kemewahan Sementara: Apa sahaja perhiasan, kenderaan, atau pakaian mewah yang membuatkan manusia terpegun di dunia hanyalah bayangan kecil yang tiada nilai berbanding nikmat Syurga.", "Pengorbanan Di Dunia Dibalas Dengan Kemuliaan Abadi: Sa'ad bin Mu'adh RA mengorbankan keselesaan hidupnya di Madinah demi membela Rasulullah S.A.W., lalu Allah menggantikannya dengan kemewahan Syurga yang tiada tandingan.", "Bimbingan Pemimpin Meluruskan Pandangan Hati: Rasulullah S.A.W. sentiasa mengalihkan perhatian para sahabat daripada terpesona dengan benda material kepada mengejar ganjaran akhirat yang kekal.", "Adakah hati kita masih mudah rasa rendah diri apabila melihat kemewahan dunia orang lain, sedangkan Allah menjanjikan Syurga buat hamba yang bertaqwa?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1035, "siri": "Sirah-02", "no": 5, "nama": "Sa'ad bin Mu'adh", "tajuk": "Saidina Sa'ad bin Mu'adh RA — Keputusan Hakim Yang Bertepatan Dengan Hukum Di Langit", "lokasi": "Zulkaedah 5 Hijrah (Mac 627 M) | Peristiwa Bani Quraizah, Madinah", "subtema": "Ketua Ansar (Aws)", "ibrah": "Ketegasan Prinsip Keadilan Walaupun Diuji Kesakitan", "sumber": "Sahih Al-Bukhari 3804", "link": "https://sunnah.com/bukhari:3804", "tema": "Kepimpinan & Keberanian", "hook": "\"Bangunlah kamu semua untuk menyambut penghulu (ketua) kamu!\"", "body": ["Perintah penghormatan luar biasa itu diucapkan oleh Rasulullah S.A.W. ketika Saidina Sa'ad bin Mu'adh RA tiba di atas seekor keldai yang dialas bantal kulit dalam keadaan tubuhnya lemah menanggung luka parah.", "Kisah ketegasan prinsip keadilan Sa'ad bin Mu'adh RA ini direkodkan oleh Abu Sa'id Al-Khudri RA di dalam Sahih Al-Bukhari.", "Semasa Perang Ahzab, ketika kota Madinah dikepung oleh 10,000 tentera musuh dari luar, puak Bani Quraizah yang sebelum itu merupakan sekutu rapat kabilah Aws (kabilah Sa'ad bin Mu'adh sendiri) telah melakukan pengkhianatan besar dengan membuka laluan serangan dari arah dalam kota.", "Selepas tentera bersekutu berundur dan Bani Quraizah dikepung selama 25 hari, mereka akhirnya menyerah diri dan meminta agar hukuman ke atas mereka diputuskan oleh ketua sekutu lama mereka, Sa'ad bin Mu'adh RA.", "Kaum keluarga Aws mengelilingi Sa'ad RA dan merayu agar beliau memberi layanan lembut kepada bekas sekutu mereka itu.", "Namun, Sa'ad bin Mu'adh RA adalah seorang pemimpin yang meletakkan prinsip keadilan agama mengatasi sentimen kabilah dan kroni!", "Beliau berkata dengan tegas:", "\"Telah tiba masanya bagi Sa'ad untuk tidak mempedulikan celaan sesiapa pun dalam menegakkan hukum Allah!\"", "Beliau kemudian menjatuhkan hukuman yang adil dan tegas ke atas pengkhianat perang tersebut mengikut ketetapan kitab mereka sendiri.", "Mendengar keputusan Sa'ad RA itu, Rasulullah S.A.W. terus bersabda:", "\"Sesungguhnya engkau telah memutuskan hukuman terhadap mereka bertepatan dengan hukum Allah (Raja segala raja) dari atas langit yang tujuh!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Keadilan Mengatasi Sentimen Kroni Dan Kabilah: Seorang pemimpin atau hakim wajib membuat keputusan berdasarkan kebenaran dan keadilan tanpa tunduk kepada pujukan rakan kongsi atau tekanan emosi.", "Jangan Takut Celaan Manusia Dalam Urusan Kebenaran: Apabila kita berdiri di atas prinsip yang benar, kita tidak perlu gentar terhadap kritikan pihak yang berkepentingan.", "Menghormati Pemimpin Yang Berjasa: Rasulullah S.A.W. memerintahkan para sahabat berdiri menyambut dan memapah Sa'ad bin Mu'adh RA sebagai tanda penghormatan tinggi terhadap wibawa serta pengorbanannya.", "Dalam membuat keputusan penting hari ini, adakah kita lebih mementingkan redha Allah atau menjaga hati manusia semata-mata?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1036, "siri": "Sirah-02", "no": 6, "nama": "Abu Talhah Al-Ansari", "tajuk": "Saidina Abu Talhah Al-Ansari RA — Mewakafkan Kebun Bairuha' Yang Paling Dicintai", "lokasi": "Fasa Madinah | Turunnya Surah Ali Imran Ayat 92", "subtema": "Tokoh Ansar", "ibrah": "Memberi Harta Paling Disayangi & Menyantuni Kerabat", "sumber": "Sahih Al-Bukhari 3792", "link": "https://sunnah.com/bukhari:3792", "tema": "Infaq & Harta", "hook": "\"Kamu sekali-kali tidak akan mencapai hakikat kebajikan yang sempurna sehinggalah kamu menginfaqkan sebahagian daripada harta yang paling kamu cintai!\" (Surah Ali Imran: 92).", "body": ["Sebaik sahaja ayat Al-Quran ini turun di Madinah, seorang hartawan Ansar tidak mencari harta lama atau barang terpakai untuk disedekahkan — sebaliknya beliau terus menyerahkan aset kebun paling mahal dan paling disayanginya!", "Kisah luar biasa Saidina Abu Talhah Zaid bin Sahl Al-Ansari RA ini diriwayatkan oleh anak tirinya, Anas bin Malik RA di dalam Sahih Al-Bukhari.", "Di seluruh kota Madinah, Abu Talhah RA merupakan seorang sahabat Ansar yang memiliki paling banyak harta kebun pohon kurma.", "Antara kesemua aset miliknya, harta yang paling beliau sayangi ialah sebuah kebun subur bernama Bairuha' yang terletak betul-betul berhadapan dengan Masjid Nabawi.", "Rasulullah S.A.W. sendiri sering masuk berehat di bawah teduhan pohon kebun Bairuha' itu dan meminum airnya yang sangat sejuk serta segar.", "Apabila turunnya ayat Surah Ali Imran ayat 92, Abu Talhah RA terus bangkit menghadap Rasulullah S.A.W. lalu berkata:", "\"Wahai Rasulullah! Sesungguhnya Allah berfirman bahawa kamu tidak akan mencapai kebajikan sebenar sehingga kamu menginfaqkan apa yang paling kamu cintai. Dan sesungguhnya harta yang paling aku cintai ialah kebun Bairuha'. Maka hari ini aku jadikannya sebagai sedekah kerana Allah! Aku mengharapkan kebajikan dan simpanan pahalanya di sisi Allah, maka letakkanlah ia wahai Rasulullah di mana sahaja yang Allah tunjukkan kepadamu!\"", "Mendengar pengorbanan luar biasa itu, Rasulullah S.A.W. bersabda dengan penuh kagum:", "\"Syabas (Bakhin)! Itu adalah harta yang sangat menguntungkan, itu adalah harta yang sangat menguntungkan! Aku telah mendengar apa yang engkau ucapkan, dan aku berpandangan eloklah engkau membahagikan kebun itu kepada kaum kerabatmu yang terdekat.\"", "Dengan penuh ketaatan, Abu Talhah RA terus mengagihkan tanah kebun kesayangannya itu kepada saudara-mara dan sepupunya termasuk Hassan bin Thabit dan Ubay bin Ka'b RA!", "3 Pengajaran (Ibrah) Untuk Kita:", "Ujian Sebenar Sedekah Adalah Memberi Apa Yang Kita Sayang: Memberi lebihan harta yang tidak kita perlukan adalah perkara biasa, tetapi mengorbankan sesuatu yang amat kita cintai adalah bukti keimanan tertinggi.", "Keutamaan Bersedekah Kepada Kaum Kerabat: Rasulullah S.A.W. mengajar bahawa sedekah kepada ahli keluarga dan saudara-mara terdekat mengandungi dua ganjaran besar sekali gus: pahala sedekah dan pahala menyambung silaturahim.", "Tindakan Segera Mengamalkan Ayat Al-Quran: Para sahabat tidak membaca Al-Quran sekadar di bibir, tetapi terus mencari jalan mempraktikkan setiap ayat yang baru diturunkan.", "Apabila kita bersedekah hari ini, adakah kita memilih bahagian yang terbaik daripada rezeki kita untuk dipersembahkan kepada Allah?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1037, "siri": "Sirah-02", "no": 7, "nama": "Abu Talhah Al-Ansari", "tajuk": "Saidina Abu Talhah Al-Ansari RA — Memadamkan Lampu Demi Mengenyangkan Tetamu", "lokasi": "Fasa Madinah | Turunnya Surah Al-Hasyr Ayat 9", "subtema": "Tokoh Ansar", "ibrah": "Sifat Ithar (Mengutamakan Orang Lain) & Kerjasama Suami Isteri", "sumber": "Sahih Al-Bukhari 4889", "link": "https://sunnah.com/bukhari:4889", "tema": "Akhlak & Adab", "hook": "Di dalam rumah itu hanya ada sedikit makanan yang cukup untuk makan malam anak-anak kecil, namun pasangan suami isteri Ansar ini menidurkan anak-anak mereka, memadamkan lampu pelita, dan berpura-pura mengunyah dalam gelap supaya tetamu mereka dapat makan sehingga kenyang!", "body": ["Kisah kemuncak sifat Ithar (mengutamakan orang lain melebihi diri sendiri) milik Saidina Abu Talhah Al-Ansari RA dan isterinya Ummu Sulaim RA ini dirakamkan di dalam Sahih Al-Bukhari dan Sahih Muslim.", "Pada suatu hari, seorang lelaki yang sedang kelaparan datang menemui Rasulullah S.A.W.", "Baginda S.A.W. menghantar utusan bertanya ke rumah isteri-isteri Baginda, namun kesemua rumah Baginda pada hari itu tidak mempunyai apa-apa makanan selain air kosong sahaja!", "Lalu Rasulullah S.A.W. bertanya kepada para sahabat:", "\"Siapakah yang sanggup menerima dan menjamu tetamu ini pada malam ini? Semoga Allah merahmatinya.\"", "Seorang lelaki Ansar iaitu Abu Talhah RA bangkit menyahut, \"Saya, wahai Rasulullah!\" lalu membawa tetamu itu pulang ke rumahnya.", "Sampai di rumah, Abu Talhah RA bertanya kepada isterinya, \"Adakah kita mempunyai sebarang makanan?\"", "Isterinya menjawab, \"Demi Allah, tiada apa-apa melainkan sedikit bekalan makan malam untuk anak-anak kecil kita sahaja.\"", "Abu Talhah RA berkata dengan penuh hikmah:", "\"Kalau begitu, lekakanlah anak-anak kita dan tidurkanlah mereka. Apabila tetamu kita masuk untuk makan sebentar lagi, hidangkanlah makanan itu, kemudian bangunlah seolah-olah engkau mahu membetulkan sumbu lampu pelita lalu padamkanlah lampu tersebut. Kita berdua akan duduk bersama tetamu di dalam gelap sambil menggerakkan mulut seolah-olah kita sedang makan bersamanya!\"", "Mereka melaksanakan rancangan mulia itu dengan sempurna: tetamu tersebut makan sehingga kenyang, manakala Abu Talhah RA, isterinya, dan anak-anak mereka tidur malam itu dalam keadaan perut kosong!", "Keesokan paginya, sebaik sahaja Abu Talhah RA bertemu Rasulullah S.A.W., Baginda tersenyum lebar lalu bersabda:", "\"Sesungguhnya Allah SWT telah tertawa (atau kagum dan reda) melihat perbuatan kamu berdua terhadap tetamu kamu pada malam tadi!\"", "Dan turunlah ayat Al-Quran yang memuji kaum Ansar buat selama-lamanya di dalam Surah Al-Hasyr ayat 9: \"Dan mereka mengutamakan (orang-orang Muhajirin) atas diri mereka sendiri, sekalipun mereka sendiri berada dalam kesusahan.\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Adab Tertinggi Menjaga Emosi Tetamu: Mereka memadamkan lampu dan berpura-pura makan supaya tetamu tersebut tidak berasa segan atau bersalah jika mengetahui tuan rumah menahan lapar.", "Kerjasama Suami Isteri Dalam Kebaikan: Kejayaan amal mulia ini lahir kerana Abu Talhah RA mempunyai seorang isteri yang sama-sama beriman, sabar, dan menyokong penuh keputusan suaminya.", "Kemuliaan Sifat Ithar (Mendahulukan Orang Susah): Membantu orang lain ketika kita mewah adalah terpuji, tetapi berkongsi ketika kita sendiri sedang sempit adalah darjat keimanan para penduduk Syurga.", "Pernahkah kita merahsiakan kesusahan diri sendiri semata-mata untuk memastikan orang yang kita bantu berasa tenang dan dihormati?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1038, "siri": "Sirah-02", "no": 8, "nama": "Abu Talhah & Ummu Sulaim", "tajuk": "Saidina Abu Talhah & Ummu Sulaim RA — Kesabaran Luar Biasa Ketika Kematian Anak", "lokasi": "Fasa Madinah | Ketabahan Keluarga Ansar & Keberkatan Doa Nabi SAW", "subtema": "Keluarga Ansar", "ibrah": "Kesabaran Menghadapi Musibah & Hikmah Komunikasi", "sumber": "Sahih Al-Bukhari 1301", "link": "https://sunnah.com/bukhari:1301", "tema": "Sabar & Tawakal", "hook": "Bayangkan seorang ibu yang baru sahaja melihat anak kecil kesayangannya menghembuskan nafas terakhir di pangkuannya, namun apabila suaminya pulang keletihan pada waktu malam, beliau menghidangkan makan malam dengan tenang tanpa menangis meraung!", "body": ["Kisah ketabahan hati pasangan Ansar, Saidina Abu Talhah RA dan isterinya Ummu Sulaim RA ini direkodkan secara sahih di dalam Sahih Al-Bukhari dan Sahih Muslim.", "Abu Talhah RA mempunyai seorang anak lelaki kecil yang sangat disayanginya (Abu Umair) yang sedang jatuh sakit.", "Ketika Abu Talhah RA keluar bekerja dan berurusan pada siang hari, kanak-kanak tersebut meninggal dunia di rumah.", "Ummu Sulaim RA dengan penuh ketabahan menguruskan jenazah kecil itu, menutupinya dengan kain di satu sudut bilik, lalu berpesan kepada ahli keluarganya:", "\"Jangan sesekali ada sesiapa pun antara kamu yang memberitahu Abu Talhah tentang kematian anaknya ini sehinggalah aku sendiri yang memberitahunya!\"", "Apabila Abu Talhah RA pulang pada waktu malam dalam keadaan letih dan berpuasa, beliau terus bertanya, \"Bagaimanakah keadaan anakku?\"", "Ummu Sulaim RA menjawab dengan satu ungkapan yang benar tetapi menenangkan hati suaminya:", "\"Dia kini berada dalam keadaan yang paling tenang berbanding sebelum ini.\"", "Abu Talhah RA menyangka anaknya sudah sembuh dan sedang tidur nyenyak!", "Ummu Sulaim RA menghidangkan makan malam buat suaminya, kemudian berhias cantik melayani suaminya pada malam tersebut.", "Pada keesokan paginya, barulah Ummu Sulaim RA bertanya dengan penuh hikmah:", "\"Wahai Abu Talhah, apakah pandanganmu sekiranya suatu kaum meminjamkan sesuatu barang kepada sebuah keluarga, kemudian pemilik asal itu meminta semula barang pinjamannya — adakah keluarga itu berhak menghalangnya?\"", "Abu Talhah RA menjawab, \"Sudah tentu tidak boleh.\"", "Ummu Sulaim RA berkata dengan lembut: \"Maka bersabarlah dan harapkanlah pahala daripada Allah atas pemergian anakmu.\"", "Pagi itu, apabila Abu Talhah RA menceritakan peristiwa tersebut kepada Rasulullah S.A.W., Baginda mendoakan mereka:", "\"Semoga Allah memberkati kamu berdua pada malam kamu tadi!\"", "Para perawi di dalam Sahih Al-Bukhari menceritakan bahawa hasil daripada doa keberkatan Nabi S.A.W. itu, Ummu Sulaim RA melahirkan seorang anak lelaki bernama Abdullah, dan daripada zuriat Abdullah itu lahir sembilan orang anak lelaki yang kesemuanya menjadi ulama penghafaz Al-Quran!", "3 Pengajaran (Ibrah) Untuk Kita:", "Anak Dan Harta Adalah Pinjaman Allah: Menyedari bahawa segala nikmat di dunia hanyalah amanah pinjaman daripada Pencipta memberi kekuatan luar biasa untuk reda apabila ia diambil semula.", "Kebijaksanaan Menyampaikan Berita Berat: Ummu Sulaim RA memilih waktu dan analogi yang paling tepat agar suaminya dapat menerima berita duka itu selepas berehat dan makan, bukan ketika sedang lapar dan letih.", "Sabar Pada Detik Pertama Musibah Membawa Ganti Terbaik: Kerana kesabaran luar biasa pasangan ini, Allah menggantikan seorang anak yang pergi dengan sembilan cucu penghafaz Al-Quran.", "Apabila diuji dengan kehilangan dalam hidup, adakah kita menyambutnya dengan keluhan atau dengan keyakinan bahawa Allah bakal menggantikannya dengan yang lebih baik?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1039, "siri": "Sirah-02", "no": 9, "nama": "Abu Talhah Al-Ansari", "tajuk": "Saidina Abu Talhah Al-Ansari RA — Mematahkan Tiga Busur & Menjadi Perisai Di Uhud", "lokasi": "7 Syawal 3 Hijrah (Mac 625 M) | Medan Perang Uhud, Madinah", "subtema": "Pahlawan Ansar", "ibrah": "Keberanian Melindungi Pemimpin & Kemahiran Tepat", "sumber": "Sahih Al-Bukhari 3811", "link": "https://sunnah.com/bukhari:3811", "tema": "Kepimpinan & Keberanian", "hook": "\"Wahai Nabi Allah! Tebusanmu adalah bapa dan ibuku! Janganlah engkau mengangkat kepalamu meninjau musuh, kerana aku bimbang anak panah musuh akan mengenaimu. Biarlah leherku di hadapan lehermu!\"", "body": ["Ungkapan cinta dan keberanian luar biasa ini diucapkan oleh pahlawan Ansar, Saidina Abu Talhah Al-Ansari RA ketika melindungi Rasulullah S.A.W. di medan Uhud, sebagaimana yang diriwayatkan oleh Anas bin Malik RA di dalam Sahih Al-Bukhari.", "Semasa barisan tentera Islam kucar-kacir di Perang Uhud, Abu Talhah RA berdiri teguh di hadapan Rasulullah S.A.W. dengan memegang sebuah perisai kulit untuk melindungi tubuh Baginda.", "Abu Talhah RA terkenal sebagai seorang pemanah yang sangat gagah dan mempunyai tarikan busur yang amat kuat.", "Pada hari Perang Uhud sahaja, kerana begitu kuat dan pantas beliau menarik tali busur tanpa henti untuk menangkis serangan musuh, sebanyak dua atau tiga batang busur panah telah patah di tangannya!", "Setiap kali ada sahabat yang lalu membawa tabung berisi anak panah, Rasulullah S.A.W. sendiri akan mengarahkan sahabat tersebut:", "\"Tuangkanlah dan serahkanlah kesemua anak panah di dalam tabungmu itu kepada Abu Talhah!\"", "Dalam masa yang sama, Rasulullah S.A.W. sesekali mengangkat sedikit kepala Baginda dari belakang perisai Abu Talhah RA untuk melihat ke manakah arah setiap anak panah Abu Talhah RA jatuh mengenai musuh.", "Kerana terlalu bimbangkan keselamatan wajah Rasulullah S.A.W., Abu Talhah RA merayu:", "\"Wahai Nabi Allah! Janganlah engkau mengangkat kepalamu, aku bimbang anak panah musuh akan mengenaimu. Biarlah dadaku menjadi perisai di hadapan dadamu, dan leherku di hadapan lehermu!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Mengutamakan Keselamatan Pemimpin Melebihi Nyawa Sendiri: Bagi para sahabat Ansar, janji setia mereka pada malam Bai'ah Aqabah untuk melindungi Rasulullah S.A.W. dibuktikan dengan mempertaruhkan dada dan leher mereka di medan perang.", "Serahkan Alat Kepada Tangan Yang Paling Mahir: Rasulullah S.A.W. mengarahkan para sahabat menyerahkan bekalan anak panah mereka kepada Abu Talhah RA kerana di tangan orang yang pakar, setiap sumber akan memberi impak maksimum.", "Kekuatan Fizikal Yang Dipandu Keimanan: Kekuatan tangan Abu Talhah RA sehingga mematahkan tiga busur panah digunakan sepenuhnya untuk mempertahankan kebenaran agama.", "Sudahkah kita menggunakan kelebihan tenaga dan kepakaran yang Allah berikan kepada kita di tempat yang paling memberi impak?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1040, "siri": "Sirah-02", "no": 10, "nama": "Abu Dujanah Al-Ansari", "tajuk": "Saidina Abu Dujanah Al-Ansari RA — Pemilik Lilitan Merah Yang Menunaikan Hak Pedang Nabi", "lokasi": "7 Syawal 3 Hijrah (Mac 625 M) | Permulaan Perang Uhud, Madinah", "subtema": "Pahlawan Ansar", "ibrah": "Keberanian Menyambut Amanah Berat & Fokus Medan", "sumber": "Sahih Muslim 2470", "link": "https://sunnah.com/muslim:2470", "tema": "Kepimpinan & Keberanian", "hook": "Rasulullah S.A.W. memegang sebilah pedang di hadapan barisan tentera Islam lalu bertanya: \"Siapakah yang sanggup mengambil pedang ini daripadaku?\"", "body": ["Kisah mendebarkan yang dirakamkan oleh Anas bin Malik RA di dalam kitab Sahih Muslim ini memaparkan keberanian seorang pahlawan kaum Ansar bernama Saidina Abu Dujanah Simak bin Kharasyah RA.", "Apabila Rasulullah S.A.W. mengangkat pedang tersebut di medan Uhud, ramai pahlawan hebat menghulurkan tangan masing-masing sambil berkata, \"Saya, wahai Rasulullah! Saya!\"", "Namun, Rasulullah S.A.W. tidak terus menyerahkannya.", "Baginda menambah satu syarat berat yang membuatkan ramai sahabat menarik semula tangan mereka:", "\"Siapakah yang sanggup mengambil pedang ini dengan menunaikan haknya (tanggungjawabnya yang sebenar)?\"", "Para sahabat terdiam kerana bimbang tidak mampu menunaikan syarat berat tersebut.", "Tiba-tiba, tampil pahlawan Ansar, Abu Dujanah Simak bin Kharasyah RA lalu bertanya, \"Apakah haknya, wahai Rasulullah?\" dan beliau berkata:", "\"Saya sedia mengambilnya dengan menunaikan haknya, wahai Rasulullah!\"", "Rasulullah S.A.W. menyerahkan pedang itu ke tangan Abu Dujanah RA.", "Sebaik menerima pedang tersebut, Abu Dujanah RA mengeluarkan sehelai kain ikatan kepala berwarna merah ('isabah al-maut / lilitan berani mati) lalu mengikatnya di dahinya.", "Beliau melangkah keluar dengan langkah yang gagah di antara dua barisan tentera, lalu membelah barisan musyrikin Quraisy dan menunaikan janji setianya mempertahankan Rasulullah S.A.W. sehingga ke akhir pertempuran!", "3 Pengajaran (Ibrah) Untuk Kita:", "Jangan Hanya Berebut Jawatan Tanpa Sedia Memikul Haknya: Ramai orang suka meminta anugerah atau jawatan, tetapi hanya insan berjiwa besar seperti Abu Dujanah RA yang berani tampil apabila dituntut menunaikan tanggungjawab penuh di sebaliknya.", "Keberanian Yang Bertempat: Sikap gagah dan tegas di hadapan musuh yang mengancam keselamatan agama adalah satu keperluan strategik untuk mematahkan psikologi lawan.", "Tunaikan Janji Dengan Tindakan Nyata: Abu Dujanah RA tidak sekadar bercakap besar di hadapan Rasulullah S.A.W., tetapi membuktikannya terus di medan pertempuran.", "Apabila kita menerima sesuatu jawatan atau amanah hari ini, adakah kita benar-benar menunaikan \"hak\" tanggungjawab tersebut dengan jujur?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1041, "siri": "Sirah-02", "no": 11, "nama": "Usaid bin Hudhair", "tajuk": "Saidina Usaid bin Hudhair Al-Ansari RA — Malaikat Turun Mendengar Bacaan Surah Al-Baqarah", "lokasi": "Fasa Madinah | Kemuliaan Alunan Al-Quran Sahabat Ansar", "subtema": "Tokoh Ansar", "ibrah": "Keberkatan Menghidupkan Malam Dengan Al-Quran", "sumber": "Sahih Al-Bukhari 5018", "link": "https://sunnah.com/bukhari:5018", "tema": "Ilmu & Dakwah", "hook": "Ketika beliau sedang mengalunkan bacaan Surah Al-Baqarah di keheningan malam, tiba-tiba kudanya meronta-ronta dan di langit kelihatan naungan awan yang dipenuhi cahaya bagaikan lampu-lampu yang bergemerlapan!", "body": ["Peristiwa luar biasa yang disaksikan dengan mata kepala sendiri oleh ketua kabilah Aws, Saidina Usaid bin Hudhair Al-Ansari RA ini direkodkan secara sahih di dalam kitab Sahih Al-Bukhari.", "Usaid bin Hudhair RA terkenal sebagai salah seorang sahabat Ansar yang memiliki suara bacaan Al-Quran paling merdu dan menyentuh jiwa.", "Pada suatu malam, beliau sedang membaca Surah Al-Baqarah di kawasan tempat penjemuran kurmanya.", "Di sebelahnya, kuda tunggangannya sedang ditambat dengan tali, manakala anak lelakinya yang masih kecil bernama Yahya sedang tidur berhampiran kuda tersebut.", "Ketika Usaid RA mula mengalunkan bacaan Al-Quran, tiba-tiba kudanya melompat dan meronta-ronta.", "Apabila Usaid RA berhenti membaca, kuda itu kembali tenang dan diam.", "Beliau menyambung semula bacaannya, dan sekali lagi kuda itu meronta-ronta; apabila beliau berhenti, kuda itu kembali tenang!", "Perkara itu berulang buat kali ketiga.", "Kerana bimbang kuda tersebut akan memijak anaknya Yahya yang sedang tidur di sisi kuda itu, Usaid RA menghentikan bacaannya lalu bangun untuk mengalihkan anaknya.", "Tatkala beliau mendongak ke langit, beliau terkejut melihat satu pemandangan seperti gumpalan awan yang di dalamnya dipenuhi cahaya-cahaya terang bagaikan pelita lampu yang sedang naik semula ke angkasa!", "Keesokan paginya, Usaid RA menceritakan kejadian aneh itu kepada Rasulullah S.A.W.", "Baginda S.A.W. berkata, \"Teruskanlah membaca wahai Ibn Hudhair! Teruskanlah membaca wahai Ibn Hudhair!\"", "Setelah Usaid RA menjelaskan bahawa beliau berhenti kerana bimbangkan keselamatan anaknya Yahya dan melihat cahaya seperti lampu di langit, Rasulullah S.A.W. bersabda:", "\"Tahukah engkau apakah cahaya itu? Itu adalah para malaikat yang turun menghampiri suaramu kerana mendengar bacaan Al-Quranmu! Sekiranya engkau terus membaca sehingga waktu Subuh, nescaya para malaikat itu akan kekal di situ sehingga orang ramai dapat melihatnya pada waktu pagi tanpa tersembunyi!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Rumah Yang Dihidupkan Dengan Al-Quran Dihadiri Malaikat: Bacaan Al-Quran yang ikhlas di waktu malam mengundang ketenangan (sakinah) dan kehadiran para malaikat rahmat ke dalam rumah kita.", "Kepekaan Ibu Bapa Menjaga Keselamatan Anak: Walaupun sedang khusyuk beribadah, Usaid RA tetap peka dan mengutamakan keselamatan fizikal anaknya yang berada berdekatan haiwan tunggangan.", "Suara Yang Baik Adalah Nikmat Untuk Membaca Kalamullah: Menghiasi bacaan Al-Quran dengan suara yang merdu dan tajwid yang betul amat dicintai oleh Allah dan penduduk langit.", "Bilakah kali terakhir kita menghidupkan suasana malam di rumah kita dengan alunan bacaan Surah Al-Baqarah dan ayat-ayat suci Al-Quran?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1042, "siri": "Sirah-02", "no": 12, "nama": "Ubay bin Ka'b", "tajuk": "Saidina Ubay bin Ka'b Al-Ansari RA — Menangis Kerana Allah Menyebut Namanya", "lokasi": "Fasa Madinah | Kemuliaan Penghulu Qurra' (Ahli Al-Quran) Kaum Ansar", "subtema": "Ilmuwan Ansar", "ibrah": "Kemuliaan Ahli Al-Quran & Rendah Hati Menerima Pujian", "sumber": "Sahih Al-Bukhari 3809", "link": "https://sunnah.com/bukhari:3809", "tema": "Ilmu & Dakwah", "hook": "\"Wahai Ubay! Sesungguhnya Allah SWT telah memerintahkan aku untuk membacakan Al-Quran kepadamu!\"", "body": ["Bayangkan perasaan anda sekiranya Rasulullah S.A.W. datang bertemu anda secara peribadi lalu menyampaikan berita bahawa Tuhan sekalian alam telah menyebut nama anda di langit!", "Kisah benar yang sangat mengharukan tentang sahabat Ansar, Saidina Ubay bin Ka'b RA ini diriwayatkan oleh Anas bin Malik RA di dalam Sahih Al-Bukhari.", "Ubay bin Ka'b RA merupakan salah seorang penulis wahyu utama dan diberi gelaran oleh Rasulullah S.A.W. sebagai Aqra'ukum (orang yang paling mahir dan fasih membaca Al-Quran dalam kalangan umat Islam).", "Pada suatu hari, Rasulullah S.A.W. memanggil Ubay bin Ka'b RA lalu bersabda kepadanya:", "\"Sesungguhnya Allah telah memerintahkan aku untuk membacakan kepada engkau surah Lam yakunilladzina kafaru (Surah Al-Bayyinah).\"", "Mendengar sabda yang tidak disangka-sangka itu, Ubay bin Ka'b RA tergamam!", "Dengan suara yang bergetar menahan sebak, beliau bertanya kepada Rasulullah S.A.W.:", "\"Wahai Rasulullah... adakah Allah menyebut namaku secara khusus kepadamu?\"", "Rasulullah S.A.W. menjawab dengan lembut:", "\"Ya, Allah menyebut namamu.\"", "Sebaik sahaja mendengar jawapan \"Ya\" daripada lisan Rasulullah S.A.W., air mata Ubay bin Ka'b RA terus tumpah mengalir membasahi janggutnya!", "Beliau menangis bukan kerana sedih, tetapi kerana terlalu terharu dan tunduk syukur mengenangkan bagaimana seorang hamba kerdil di bumi Madinah boleh diingati dan disebut namanya oleh Allah SWT di langit kerana kecintaannya kepada Al-Quran.", "3 Pengajaran (Ibrah) Untuk Kita:", "Al-Quran Mengangkat Darjat Hamba Di Sisi Allah: Kemuliaan tertinggi Ubay bin Ka'b RA sehingga namanya disebut oleh Allah SWT berpunca daripada ketekunan beliau mempelajari, menghafaz, dan mengajarkan Al-Quran.", "Kerendahan Hati Rasulullah S.A.W. Terhadap Sahabat: Walaupun Baginda adalah Rasul penerima wahyu, Baginda tetap patuh membacakan surah tersebut di hadapan muridnya Ubay bin Ka'b RA sebagai penghormatan dan pengajaran bacaan.", "Sambut Penghormatan Dengan Air Mata Syukur, Bukan Kesombongan: Apabila mendapat pengiktirafan paling agung, Ubay RA tidak mendabik dada, sebaliknya menangis kerana rasa kerdil di hadapan rahmat Tuhan.", "Adakah kita sedang membina hubungan yang rapat dengan Al-Quran setiap hari agar nama kita turut diingati oleh penduduk langit?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1043, "siri": "Sirah-02", "no": 13, "nama": "Mu'adh bin Jabal", "tajuk": "Saidina Mu'adh bin Jabal Al-Ansari RA — Wasiat Cinta Nabi SAW & Doa Selepas Solat", "lokasi": "Fasa Madinah | Didikan Peribadi Rasulullah S.A.W. Kepada Pemuda Ansar", "subtema": "Ilmuwan Ansar", "ibrah": "Menjaga Zikir Selepas Solat & Mencintai Kerana Allah", "sumber": "Sunan Abu Daud 1522", "link": "https://sunnah.com/abudawud:1522", "tema": "Ilmu & Dakwah", "hook": "Rasulullah S.A.W. memegang erat tangan pemuda Ansar ini lalu bersabda: \"Wahai Mu'adh! Demi Allah, sesungguhnya aku benar-benar mencintaimu!\"", "body": ["Kisah indah yang diriwayatkan secara sahih di dalam Sunan Abu Daud ini merakamkan betapa dalamnya kasih sayang Rasulullah S.A.W. terhadap ilmuwan muda kaum Ansar, Saidina Mu'adh bin Jabal RA.", "Mu'adh bin Jabal RA memeluk Islam pada usia remaja sekitar 18 tahun dan menghadiri Bai'ah Aqabah Kedua.", "Walaupun masih muda, beliau tekun menuntut ilmu daripada Rasulullah S.A.W. sehingga Baginda mengiktiraf beliau sebagai sahabat yang paling alim tentang hukum halal dan haram dalam kalangan umat ini.", "Pada suatu hari, Rasulullah S.A.W. memegang tangan Mu'adh bin Jabal RA dengan penuh kasih sayang lalu bersabda:", "\"Wahai Mu'adh! Demi Allah, sesungguhnya aku mencintaimu! Demi Allah, sesungguhnya aku mencintaimu!\"", "Kemudian Baginda S.A.W. menyambung:", "\"Aku ingin berwasiat kepadamu wahai Mu'adh: Janganlah sesekali engkau tertinggal pada setiap penghujung solat untuk membaca doa ini: Allahumma a'inni 'ala dzikrika, wa syukrika, wa husni 'ibadatik (Ya Allah, bantulah aku untuk sentiasa mengingati-Mu, bersyukur kepada-Mu, dan memperelokkan ibadahku kepada-Mu).\"", "Mu'adh bin Jabal RA menjaga wasiat cinta daripada Rasulullah S.A.W. itu sepanjang hayatnya tanpa pernah meninggalkannya walau satu waktu solat pun!", "Malah sebelum beliau wafat, Mu'adh RA mewasiatkan doa yang sama kepada muridnya As-Sunabihi, dan muridnya pula mewasiatkannya kepada generasi seterusnya sehingga doa agung ini sampai kepada kita pada hari ini.", "3 Pengajaran (Ibrah) Untuk Kita:", "Zahirkan Kasih Sayang Dan Penghargaan Secara Lisan: Rasulullah S.A.W. mengajar kita supaya tidak lokek menyatakan rasa sayang dan penghargaan kepada anak murid, sahabat, atau ahli keluarga demi menguatkan ikatan hati.", "Hadiah Terbaik Kepada Orang Tersayang Adalah Ilmu Akhirat: Selepas menyatakan cinta kepada Mu'adh RA, hadiah yang diberikan oleh Rasulullah S.A.W. bukanlah emas atau perak, tetapi amalan doa yang menyelamatkan dunia dan akhirat.", "Kita Tidak Mampu Beribadah Tanpa Bantuan Allah: Doa pendek ini mengajar kita bahawa kekuatan untuk berzikir, bersyukur, dan beribadah dengan baik semuanya memerlukan pertolongan (i'anah) daripada Allah SWT.", "Sudahkah kita mengamalkan doa wasiat Rasulullah S.A.W. kepada Mu'adh bin Jabal RA ini setiap kali selesai menunaikan solat fardu?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1044, "siri": "Sirah-02", "no": 14, "nama": "Mu'adh bin Jabal", "tajuk": "Saidina Mu'adh bin Jabal Al-Ansari RA — Duta Muda Ke Yaman & Strategi Keutamaan", "lokasi": "10 Hijrah (631 M) | Pengutusan Mu'adh bin Jabal RA Ke Bumi Yaman", "subtema": "Ilmuwan Ansar", "ibrah": "Strategi Berperingkat Dalam Pendidikan & Keadilan Zakat", "sumber": "Sahih Al-Bukhari 4347", "link": "https://sunnah.com/bukhari:4347", "tema": "Ilmu & Dakwah", "hook": "Ketika menghantar pemuda Ansar ini sebagai gabenor dan hakim ke bumi Yaman, Rasulullah S.A.W. membekalkannya dengan satu carta alir (SOP) kepimpinan dan dakwah yang paling sistematik dalam sejarah!", "body": ["Kisah sahih yang menjadi rujukan utama para ulama dan pemimpin ini direkodkan di dalam Sahih Al-Bukhari dan Sahih Muslim.", "Apabila penduduk Yaman memeluk Islam, Rasulullah S.A.W. memilih Saidina Mu'adh bin Jabal RA untuk menjadi wakil kerajaan Islam Madinah bagi mendidik masyarakat, menjadi hakim, dan menguruskan pentadbiran zakat di sana.", "Sebelum Mu'adh RA berangkat, Rasulullah S.A.W. memberi taklimat strategik yang amat jelas:", "\"Wahai Mu'adh! Sesungguhnya engkau akan mendatangi satu kaum daripada kalangan Ahli Kitab (yang berilmu dan mempunyai latar belakang agama). Maka apabila engkau tiba kepada mereka, hendaklah perkara pertama yang engkau serukan ialah mengajak mereka bersaksi bahawa tiada Tuhan yang berhak disembah melainkan Allah dan bahawa Muhammad itu pesuruh Allah.\"", "Baginda menyambung langkah demi langkah mengikut urutan keutamaan:", "\"Sekiranya mereka telah mentaati engkau dalam perkara tauhid itu, barulah engkau beritahu mereka bahawa Allah telah mewajibkan ke atas mereka solat lima waktu sehari semalam. Sekiranya mereka telah mentaati perkara itu, barulah engkau beritahu mereka bahawa Allah telah mewajibkan ke atas mereka zakat yang diambil daripada golongan kaya dalam kalangan mereka dan diagihkan semula kepada golongan fakir miskin dalam kalangan mereka!\"", "Dan Baginda menutup dengan satu amaran tegas tentang keadilan:", "\"Apabila mereka mentaatinya, janganlah engkau mengambil harta terbaik kesayangan mereka secara berlebihan, dan takutlah kamu kepada doa orang yang dizalimi, kerana sesungguhnya antara doa orang yang dizalimi dengan Allah tiada sebarang penghalang (hijab)!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Kuasai Fiqh Keutamaan (Susun Ikut Kepentingan): Dalam mendidik keluarga, mengurus pekerja, atau menyampaikan dakwah, mulakan dengan membina asas keyakinan (mindset/tauhid) terlebih dahulu sebelum membebankan mereka dengan cabang peraturan.", "Kenali Latar Belakang Audiens Anda: Rasulullah S.A.W. mengingatkan Mu'adh RA tentang profil masyarakat Yaman supaya beliau bersedia dengan hujah ilmu yang sesuai dengan tahap pemikiran mereka.", "Zakat Dan Kekayaan Adalah Untuk Keadilan Sosial Tempatan: Sistem ekonomi Islam memastikan kekayaan yang dikumpul daripada orang berada diagihkan terus untuk membasmi kemiskinan masyarakat di tempat itu sendiri tanpa sebarang penindasan.", "Adakah kita sudah menyusun keutamaan dalam mendidik anak-anak dan pasukan kita mengikut tertib yang diajarkan oleh Rasulullah S.A.W.?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1045, "siri": "Sirah-02", "no": 15, "nama": "Anas bin Malik", "tajuk": "Saidina Anas bin Malik Al-Ansari RA — 10 Tahun Berkhidmat Tanpa Pernah Ditegur \"Ah!\"", "lokasi": "1 Hijrah hingga 11 Hijrah (622 M - 632 M) | Madinah Al-Munawwarah", "subtema": "Pembantu Nabi (Ansar)", "ibrah": "Akhlak Kepimpinan, Kesabaran Mendidik & Kesetiaan", "sumber": "Sahih Al-Bukhari 6038", "link": "https://sunnah.com/bukhari:6038", "tema": "Akhlak & Adab", "hook": "Bayangkan seorang kanak-kanak berumur 10 tahun bekerja menguruskan keperluan seorang pemimpin besar selama 10 tahun berturut-turut, namun sepanjang sedekad itu beliau tidak pernah dimarahi atau mendengar keluhan \"Ah!\" walau sekali pun!", "body": ["Kesaksian tulus daripada pembantu rapat Rasulullah S.A.W., Saidina Anas bin Malik Al-Ansari RA ini direkodkan secara sahih di dalam Sahih Al-Bukhari dan Sahih Muslim.", "Ketika Rasulullah S.A.W. baru tiba di Madinah, ibu Anas iaitu Ummu Sulaim RA memegang tangan Anas yang baru berusia 10 tahun lalu membawanya kepada Baginda S.A.W. sambil berkata:", "\"Wahai Rasulullah, semua lelaki dan wanita Ansar telah memberikan hadiah kepadamu. Aku tidak mempunyai apa-apa harta untuk dihadiahkan melainkan anak kecilku ini; ambillah dia untuk berkhidmat kepadamu!\"", "Sejak umur 10 tahun sehingga usia 20 tahun ketika kewafatan Rasulullah S.A.W., Anas bin Malik RA berada di sisi Baginda siang dan malam.", "Apakah kesaksian Anas RA tentang akhlak majikannya itu?", "Anas RA berkata di dalam Sahih Al-Bukhari:", "\"Aku telah berkhidmat kepada Nabi S.A.W. selama sepuluh tahun. Demi Allah, Baginda tidak pernah sekali pun berkata kepadaku 'Uff' (perkataan keluhan paling kecil seperti 'Cis' atau 'Ah'), dan Baginda tidak pernah menegurku atas sesuatu yang aku lakukan dengan berkata: 'Mengapa engkau buat begini?' atau terhadap sesuatu yang aku terlupa buat dengan berkata: 'Mengapa engkau tidak buat begini?'\"", "Malah dalam riwayat Sahih Muslim, Anas RA menceritakan bagaimana suatu hari Rasulullah S.A.W. menyuruhnya pergi menyelesaikan satu tugasan, namun di pertengahan jalan Anas yang masih kanak-kanak telah leka bermain bersama budak-budak lain di pasar.", "Tiba-tiba Anas terasa seseorang memegang belakang lehernya dari belakang — apabila beliau menoleh, kelihatan Rasulullah S.A.W. sedang tersenyum manis kepadanya lalu bertanya dengan lembut: \"Wahai Unais (panggilan manja buat Anas), sudahkah engkau pergi ke tempat yang aku suruh tadi?\"", "Dan berkat khidmatnya itu, Rasulullah S.A.W. mendoakan Anas RA agar dikurniakan harta yang banyak, anak yang ramai, dan usia yang panjang lagi diberkati — sehingga Anas RA hidup melebihi usia 100 tahun dengan kebun yang berbuah dua kali setahun!", "3 Pengajaran (Ibrah) Untuk Kita:", "Kesabaran Luar Biasa Dalam Mendidik Orang Bawahan: Kemuncak kematangan seorang ketua atau ibu bapa adalah keupayaan mengawal lidah daripada mengeluh dan memarahi kesilapan tidak sengaja anak buah atau anak kecil.", "Teguran Dengan Senyuman Lebih Membina Daripada Tengkingan: Cara Rasulullah S.A.W. menyapa Anas RA dengan panggilan manja dan senyuman membuatkan Anas RA berasa sangat malu untuk mengulangi kecuaiannya, malah melahirkan ketaatan seumur hidup.", "Doa Keberkatan Buat Pekerja Yang Setia: Menghargai khidmat pembantu atau pekerja dengan doa yang baik dan layanan bermaruah akan melimpahkan keberkatan kepada kedua-dua belah pihak.", "Bagaimanakah layanan dan tutur kata kita terhadap pekerja, pembantu, atau anak-anak kita apabila mereka tersilap melakukan sesuatu tugasan hari ini?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1046, "siri": "Sirah-02", "no": 16, "nama": "Ka'ab bin Malik", "tajuk": "Saidina Ka'ab bin Malik Al-Ansari RA — 50 Hari Dipulaukan & Kejujuran Yang Menyelamatkan Iman", "lokasi": "Rejab – Zulkaedah 9 Hijrah (630 M) | Selepas Kepulangan Dari Perang Tabuk", "subtema": "Penyair Ansar", "ibrah": "Kuasa Berkata Benar, Bahaya Bertangguh & Taubat Nasuha", "sumber": "Sahih Al-Bukhari 4418", "link": "https://sunnah.com/bukhari:4418", "tema": "Taubat & Hidayah", "hook": "Ketika lebih 80 orang yang ponteng perang datang mereka-reka seribu satu alasan palsu untuk menyelamatkan diri, sahabat Ansar ini memilih untuk berterus terang walaupun terpaksa menanggung ujian pemulauan selama 50 hari sehingga bumi Madinah terasa sempit!", "body": ["Kisah taubat agung Saidina Ka'ab bin Malik Al-Ansari RA ini dirakamkan secara panjang lebar di dalam Sahih Al-Bukhari dan diabadikan di dalam Surah At-Taubah ayat 118.", "Semasa Rasulullah S.A.W. menyeru umat Islam keluar ke Perang Tabuk, Ka'ab bin Malik RA sebenarnya berada pada tahap kesihatan dan kemampuan kewangan yang paling baik — beliau siap memiliki dua ekor unta tunggangan!", "Namun penyakit \"bertangguh\" menjerat dirinya.", "Setiap pagi beliau berkata di dalam hati, \"Esok aku akan bersiap...\" sehinggalah tentera Islam sudah bergerak jauh meninggalkan Madinah dan beliau tertinggal di belakang tanpa sebarang uzur!", "Apabila Rasulullah S.A.W. pulang ke Madinah, golongan munafik berduyun-duyun datang bersumpah palsu memberi alasan sakit atau masalah keluarga.", "Tiba giliran Ka'ab bin Malik RA duduk di hadapan Rasulullah S.A.W., Baginda tersenyum dengan senyuman orang yang marah lalu bertanya, \"Apakah yang menyebabkan engkau tertinggal?\"", "Ka'ab RA seorang penyair hebat yang petah berkata-kata; beliau tahu jika beliau berbohong, pasti beliau boleh lepas.", "Namun Ka'ab RA berkata:", "\"Wahai Rasulullah! Demi Allah, sekiranya aku duduk di hadapan mana-mana pembesar dunia selain engkau, pasti aku mampu mengelak kemarahannya dengan alasan lidahku. Tetapi demi Allah, aku tahu jika hari ini aku berbohong kepadamu sehingga engkau reda kepadaku, pasti Allah akan membuatkan engkau murka kepadaku! Sebaliknya jika aku bercakap benar kepadamu sehingga engkau marah kepadaku, aku mengharapkan keampunan Allah. Demi Allah, aku tiada sebarang uzur! Aku tidak pernah sekuat dan semudah hari ketika aku tertinggal daripadamu itu!\"", "Rasulullah S.A.W. bersabda: \"Adapun orang ini, sesungguhnya dia telah bercakap benar! Maka bangunlah sehinggalah Allah menurunkan keputusan-Nya tentang dirimu.\"", "Selama 50 hari berturut-turut, Ka'ab RA bersama dua sahabat Ansar yang lain (Murarah bin Ar-Rabi' dan Hilal bin Umayyah) diuji dengan perintah pemulauan sosial: tiada seorang pun penduduk Madinah dibenarkan bercakap dengan mereka!", "Di kemuncak ujian itu, Raja Ghassan yang beragama Kristian menghantar surat menawarkan suaka politik dan kemewahan kepada Ka'ab RA, namun Ka'ab RA terus membakar surat itu di dalam dapur api!", "Pada pagi hari ke-50, turunlah wahyu Surah At-Taubah ayat 118 yang mengisytiharkan penerimaan taubat mereka bertiga kerana kejujuran mutlak mereka kepada Allah dan Rasul-Nya!", "3 Pengajaran (Ibrah) Untuk Kita:", "Bahaya Penyakit Bertangguh (Procrastination): Ka'ab RA tidak berniat menderhaka, tetapi sikap menangguhkan persiapan dari sehari ke sehari akhirnya menyebabkan beliau terlepas peluang besar bersama Rasulullah S.A.W.", "Kejujuran Itu Pahit Pada Permulaan, Tetapi Manis Pada Pengakhiran: Bercakap benar ketika melakukan kesilapan mungkin mengundang teguran sementara, namun ia menyelamatkan maruah dan iman kita buat selama-lamanya.", "Jangan Gadaikan Prinsip Ketika Diuji Oleh Pemimpin: Walaupun sedang ditegur dan diuji hebat di Madinah, Ka'ab RA membakar tawaran musuh dari Ghassan kerana kesetiaannya kepada Islam tidak boleh dibeli.", "Apabila kita tersilap langkah dalam kerja atau kehidupan, adakah kita berani mengakui kesilapan secara jujur atau mencari alasan menyalahkan keadaan?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1047, "siri": "Sirah-02", "no": 17, "nama": "Thabit bin Qais", "tajuk": "Saidina Thabit bin Qais Al-Ansari RA — Menangis Kerana Suara Lantang, Lalu Dijamin Syurga", "lokasi": "9 Hijrah (630 M) | Turunnya Surah Al-Hujurat Ayat 2 Di Madinah", "subtema": "Jurucakap Ansar", "ibrah": "Sensitiviti Terhadap Ayat Allah & Husnuzon Sesama Sahabat", "sumber": "Sahih Muslim 119a", "link": "https://sunnah.com/muslim:119a", "tema": "Akhlak & Adab", "hook": "Hanya kerana suaranya secara semula jadi kuat dan lantang, sahabat Ansar ini mengurung diri di dalam rumah sambil menangis kerana menyangka seluruh amalannya telah gugur dan dirinya bakal masuk Neraka!", "body": ["Kisah yang sangat menyentuh hati tentang jurucakap rasmi Rasulullah S.A.W. dan kaum Ansar, Saidina Thabit bin Qais bin Syammas RA ini direkodkan secara sahih di dalam Sahih Al-Bukhari dan Sahih Muslim.", "Thabit bin Qais RA dikurniakan oleh Allah suara yang amat lantang dan bersemangat, sehingga beliau dilantik sebagai Khatib Al-Ansar (pemidato dan jurucakap utama bagi pihak Rasulullah S.A.W. apabila menyambut delegasi luar).", "Namun pada suatu hari, turunlah ayat ke-2 daripada Surah Al-Hujurat:", "\"Wahai orang-orang yang beriman! Janganlah kamu mengangkat suara kamu melebihi suara Nabi, dan janganlah kamu menyaringkan suara kepada Baginda sebagaimana kamu menyaringkan suara sesama kamu, kerana dikhuatiri segala amalan kamu akan gugur terhapus sedangkan kamu tidak menyedarinya!\"", "Sebaik sahaja mendengar ayat Al-Quran itu, Thabit bin Qais RA terus menggigil ketakutan!", "Beliau pulang mengunci diri di dalam rumahnya dan menangis teresak-esak sambil berkata:", "\"Akulah orang yang paling kuat suaranya di hadapan Rasulullah S.A.W.! Pasti segala amalanku telah terhapus dan aku termasuk dalam kalangan ahli Neraka!\"", "Setelah beberapa hari Thabit RA tidak kelihatan di Masjid Nabawi, Rasulullah S.A.W. bertanya kepada jirannya, Sa'ad bin Mu'adh RA (atau para sahabat Ansar): \"Apakah yang berlaku kepada Thabit? Adakah dia jatuh sakit?\"", "Apabila Sa'ad RA pergi menziarahi Thabit RA dan mendengar tangisan ketakutannya terhadap ayat Surah Al-Hujurat itu, beliau segera kembali memaklumkannya kepada Rasulullah S.A.W.", "Mendengar kegusaran hati Thabit RA itu, Rasulullah S.A.W. bersabda dengan satu berita gembira yang mengangkat segala dukanya:", "\"Pergilah beritahu kepadanya: Sesungguhnya engkau bukanlah daripada kalangan ahli Neraka, bahkan engkau adalah daripada kalangan penghuni Syurga!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Hati Yang Hidup Sentiasa Sensitif Dengan Teguran Al-Quran: Apabila mendengar ayat amaran daripada Allah, para sahabat tidak menuding jari kepada orang lain, sebaliknya terus memeriksa kelemahan diri sendiri terlebih dahulu.", "Allah Menilai Niat, Bukan Sifat Semula Jadi Yang Tidak Disengajakan: Suara Thabit RA yang lantang adalah fitrah kejadiannya dan digunakan untuk membela Islam, bukan kerana kurang adab terhadap Rasulullah S.A.W.", "Kepekaan Pemimpin Mengambil Berat Kehilangan Anak Buah: Rasulullah S.A.W. segera menyedari ketiadaan Thabit RA di masjid dan menghantar sahabat untuk bertanya khabar keadaannya.", "Apabila kita mendengar nasihat agama atau teguran yang baik, adakah kita menjadikannya cermin untuk memperbaiki diri sendiri?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1048, "siri": "Sirah-02", "no": 18, "nama": "Abu Ayyub Al-Ansari", "tajuk": "Saidina Abu Ayyub Al-Ansari RA — Tuan Rumah Yang Tidak Sanggup Berjalan Di Tingkat Atas", "lokasi": "Rabiulawal 1 Hijrah (September 622 M) | Ketibaan Rasulullah S.A.W. Di Madinah", "subtema": "Tokoh Ansar", "ibrah": "Kemuncak Adab Menghormati Tetamu & Mencintai Sunnah", "sumber": "Sahih Muslim 2053c", "link": "https://sunnah.com/muslim:2053c", "tema": "Akhlak & Adab", "hook": "Semalaman pasangan suami isteri Ansar ini tidak berani melelapkan mata dan hanya mengesot di tepi dinding bilik kerana terlalu takut berada di tingkat atas sedangkan Rasulullah S.A.W. berada di tingkat bawah rumah mereka!", "body": ["Kisah kemuncak adab dan kecintaan Saidina Abu Ayyub Khalid bin Zaid Al-Ansari RA terhadap Rasulullah S.A.W. ini dirakamkan secara sahih di dalam kitab Sahih Muslim.", "Ketika Rasulullah S.A.W. tiba di Madinah semasa peristiwa Hijrah, setiap ketua kabilah Ansar memegang tali kekang unta Baginda (Al-Qaswa') kerana berebut mahu menjadi tuan rumah kepada Baginda.", "Rasulullah S.A.W. bersabda dengan penuh hikmah: \"Biarkanlah unta ini berjalan, kerana ia diperintahkan oleh Allah.\"", "Akhirnya unta Baginda berhenti dan melutut betul-betul di hadapan rumah Abu Ayyub Al-Ansari RA!", "Bagi memudahkan para tetamu datang menziarahi Baginda, Rasulullah S.A.W. memilih untuk tinggal di tingkat bawah rumah tersebut, manakala Abu Ayyub RA dan isterinya tinggal di tingkat atas.", "Namun pada waktu malam, Abu Ayyub RA tersedar dan berasa amat gelisah:", "\"Bagaimana mungkin kita berjalan di atas bumbung sedangkan wahyu langit turun kepada Rasulullah S.A.W. di bawah tapak kaki kita?!\"", "Malam itu juga, bekas air mereka pecah tumpah di tingkat atas; kerana takut walau setitis air menitis jatuh mengenai Rasulullah S.A.W. di bawah, Abu Ayyub RA dan isterinya segera menggunakan satu-satunya kain selimut tebal milik mereka untuk mengelap lantai sehingga kering!", "Keesokan paginya, Abu Ayyub RA merayu kepada Rasulullah S.A.W. sehingga Baginda bersetuju berpindah ke tingkat atas, manakala Abu Ayyub RA berpindah ke tingkat bawah.", "Bukan itu sahaja — setiap kali Abu Ayyub RA menghantar hidangan makanan kepada Rasulullah S.A.W. dan dulang makanan itu dipulangkan semula, beliau akan bertanya kepada pembawa dulang di bahagian manakah jari-jemari mulia Baginda S.A.W. menyentuh makanan tersebut, lalu beliau makan tepat di bekas sentuhan jari Baginda demi mengambil keberkatan!", "3 Pengajaran (Ibrah) Untuk Kita:", "Adab Mendahului Segala-galanya: Kemuliaan Abu Ayyub Al-Ansari RA terpahat dalam sejarah kerana tingginya rasa hormat dan adab beliau dalam memuliakan Rasulullah S.A.W. di rumahnya.", "Keikhlasan Mencintai Sunnah Dan Peribadi Nabi: Kecintaan para sahabat terhadap Rasulullah S.A.W. bukan sekadar slogan, tetapi dizahirkan melalui rasa hormat terhadap setiap perkara yang berkaitan dengan Baginda.", "Semangat Perjuangan Yang Tidak Luntur Hingga Usia Emas: Abu Ayyub Al-Ansari RA terus berjuang menyebarkan Islam sehingga wafat di hadapan tembok kota Constantinople (Istanbul) pada usia lebih 80 tahun!", "Sejauh manakah kita menerapkan adab menghormati tetamu, guru, dan sunnah Rasulullah S.A.W. di dalam rumah tangga kita hari ini?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1049, "siri": "Sirah-02", "no": 19, "nama": "Jabir bin Abdullah", "tajuk": "Saidina Jabir bin Abdullah Al-Ansari RA — Unta Tua Yang Dibeli Lalu Dipulangkan Percuma", "lokasi": "Fasa Madinah | Perjalanan Pulang Dari Ekspedisi Perang Bersama Nabi SAW", "subtema": "Tokoh Muda Ansar", "ibrah": "Empati Pemimpin Terhadap Kesempitan Anak Buah & Berkat", "sumber": "Sahih Al-Bukhari 2097", "link": "https://sunnah.com/bukhari:2097", "tema": "Akhlak & Adab", "hook": "Rasulullah S.A.W. membeli unta milik pemuda Ansar yang sedang menanggung hutang ayahnya ini, namun apabila tiba di Madinah, Baginda membayar penuh harga emas unta itu DAN memulangkan semula unta tersebut kepadanya secara percuma!", "body": ["Kisah yang sangat manis dan menyentuh hati antara Rasulullah S.A.W. dengan sahabat muda Ansar, Saidina Jabir bin Abdullah RA ini direkodkan secara sahih di dalam Sahih Al-Bukhari.", "Ayah Jabir iaitu Abdullah bin Amr bin Haram RA telah gugur syahid dalam Perang Uhud dengan meninggalkan beban hutang yang banyak serta sembilan (atau tujuh) orang anak perempuan di bawah tanggungan Jabir RA yang masih muda.", "Dalam satu ekspedisi perjalanan pulang ke Madinah bersama Rasulullah S.A.W., unta tunggangan Jabir RA terlalu tua, kurus, dan keletihan sehingga tertinggal di barisan paling belakang.", "Tiba-tiba, Rasulullah S.A.W. sendiri datang dari arah belakang menghampiri Jabir RA!", "Baginda bertanya, \"Mengapakah untamu ini wahai Jabir?\"", "Jabir RA menjawab, \"Ia sudah terlalu letih dan perlahan, wahai Rasulullah.\"", "Rasulullah S.A.W. mendoakan unta tersebut dan menyentuhnya sedikit, lalu dengan izin Allah unta tua itu tiba-tiba menjadi sangat cergas dan berlari pantas mendahului unta-unta yang lain!", "Sambil menunggang di sebelah Jabir RA, Rasulullah S.A.W. berbual mesra bertanya khabar perkahwinan Jabir, bagaimana Jabir mengahwini seorang wanita janda yang matang demi menjaga adik-adik perempuannya yang masih kecil, serta bertanyakan baki hutang peninggalan ayahnya.", "Kemudian Rasulullah S.A.W. bersabda: \"Juallah untamu ini kepadaku, wahai Jabir!\"", "Setelah mereka berunding harga dan tiba di Madinah, Jabir RA membawa unta itu untuk diserahkan kepada Rasulullah S.A.W.", "Baginda S.A.W. mengarahkan Bilal RA menimbang bayaran emas harga unta tersebut dengan tambahan berat yang lebih buat Jabir RA.", "Sebaik sahaja Jabir RA menerima wang emas itu dan berpusing mahu pulang, Rasulullah S.A.W. memanggilnya semula lalu bersabda:", "\"Ambillah wang harga bayaran itu, dan ambillah semula untamu ini balik bersama-samamu; ia kekal menjadi milikmu!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Cara Halus Pemimpin Membantu Anak Buah Tanpa Menjatuhkan Maruah: Rasulullah S.A.W. tahu Jabir RA memerlukan wang untuk melunaskan hutang ayahnya dan menyara adik-adiknya, lalu Baginda menggunakan akad jual beli terlebih dahulu sebelum menghadiahkan semula unta itu supaya Jabir RA tidak berasa seperti peminta sedekah.", "Pengorbanan Anak Sulung Demi Adik-Beradik: Jabir RA mengetepikan kehendak peribadinya ketika berkahwin semata-mata untuk memilih pasangan yang mampu membantu mendidik dan menyikat rambut adik-adik perempuannya yang yatim.", "Pemimpin Yang Baik Berada Di Belakang Untuk Menjaga Yang Lemah: Rasulullah S.A.W. sering berjalan di barisan belakang rombongan supaya Baginda dapat membantu sesiapa yang keletihan atau ketinggalan.", "Apabila kita ingin menghulurkan bantuan kewangan kepada saudara atau pekerja yang sempit, adakah kita menjaga air muka dan maruah mereka seperti yang ditunjukkan oleh Rasulullah S.A.W.?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1050, "siri": "Sirah-02", "no": 20, "nama": "Julaybib RA", "tajuk": "Saidina Julaybib RA — Disisihkan Manusia, Namun Dicari Oleh Rasulullah SAW", "lokasi": "Fasa Madinah | Kemuliaan Syuhada' Di Sisi Allah SWT", "subtema": "Syuhada' Ansar", "ibrah": "Kemuliaan Di Sisi Allah Mengatasi Status Sosial Dunia", "sumber": "Sahih Muslim 2472", "link": "https://sunnah.com/muslim:2472", "tema": "Akhlak & Adab", "hook": "\"Dia adalah sebahagian daripadaku, dan aku adalah sebahagian daripadanya!\"", "body": ["Sabda penuh kasih sayang daripada Rasulullah S.A.W. ini diucapkan sebanyak dua kali ketika Baginda sendiri mengangkat jasad seorang sahabat kerdil yang dahulunya dipandang rendah oleh masyarakat!", "Kisah benar yang meruntuhkan segala kesombongan darjat dan rupa paras manusia ini diriwayatkan oleh Abu Barzah Al-Aslami RA di dalam kitab Sahih Muslim.", "Di Madinah, terdapat seorang sahabat bernama Julaybib RA yang tidak mempunyai kedudukan kabilah yang tinggi, miskin harta, dan memiliki rupa paras serta fizikal yang kerdil sehingga orang ramai kurang mempedulikannya.", "Namun di sisi Rasulullah S.A.W., nilai seorang insan diukur pada ketaqwaan hatinya!", "Rasulullah S.A.W. sendiri pergi meminang seorang gadis Ansar buat Julaybib RA.", "Ketika ibu bapa gadis itu teragak-agak kerana status Julaybib RA, gadis Ansar yang beriman itu tampil berkata:", "\"Adakah ayah dan ibu mahu menolak urusan yang dibawa sendiri oleh Rasulullah S.A.W.? Serahkanlah aku kepadanya, kerana sesungguhnya Rasulullah S.A.W. tidak akan mensia-siakan hidupku!\"", "Rasulullah S.A.W. mendoakan pasangan itu: \"Ya Allah, limpahkanlah kebaikan ke atas mereka dengan selimpah-limpahnya dan janganlah Engkau jadikan kehidupan mereka sukar.\"", "Tidak lama kemudian, berlaku satu peperangan dan Julaybib RA keluar berjuang di jalan Allah.", "Selepas pertempuran tamat, Rasulullah S.A.W. bertanya kepada para sahabat:", "\"Periksalah, adakah kamu kehilangan sesiapa daripada kalangan kamu?\"", "Para sahabat menyebut nama beberapa tokoh terkenal daripada keluarga masing-masing yang terkorban.", "Rasulullah S.A.W. bertanya lagi buat kali kedua, dan mereka masih menyebut nama orang-orang kenamaan sahaja.", "Akhirnya Rasulullah S.A.W. bersabda:", "\"Tetapi aku sedang mencari dan merindui Julaybib! Pergilah kamu cari di manakah dia!\"", "Apabila mereka mencarinya di medan pertempuran, mereka menemui jasad Julaybib RA telah gugur syahid di sisi tujuh orang musuh yang telah berjaya ditewaskannya sebelum beliau rebah!", "Rasulullah S.A.W. datang berdiri di sisi jenazah Julaybib RA lalu bersabda:", "\"Dia telah menewaskan tujuh orang musuh kemudian dia gugur syahid! Dia ini adalah daripadaku dan aku adalah daripadanya! Dia ini adalah daripadaku dan aku adalah daripadanya!\"", "Kemudian Rasulullah S.A.W. sendiri memangku jasad Julaybib RA di atas kedua-dua lengan Baginda tanpa sebarang pengusung lain sehinggalah liang lahad siap digali dan Baginda sendiri meletakkannya ke dalam kubur!", "3 Pengajaran (Ibrah) Untuk Kita:", "Jangan Sesekali Memandang Rendah Insan Yang Kelihatan Kerdil: Seseorang yang tiada pangkat, harta, atau rupa di mata masyarakat mungkin memiliki kedudukan yang sangat mulia di hati Rasulullah S.A.W. dan di sisi Allah.", "Keberkatan Menerima Pilihan Agama: Gadis Ansar yang menerima pinangan Rasulullah S.A.W. buat Julaybib RA memperoleh keberkatan doa Nabi S.A.W. sehingga menjadi antara balu paling diberkati rezekinya di Madinah.", "Pemimpin Sejati Mengingati Setiap Ahli Pasukannya: Ketika orang lain hanya mengingati tokoh-tokoh terkenal, Rasulullah S.A.W. mencari dan memuliakan insan yang dilupakan oleh orang ramai.", "Adakah layanan kita terhadap manusia hari ini masih dipengaruhi oleh pangkat dan rupa paras mereka, atau kita memuliakan setiap insan kerana Allah?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1051, "siri": "Sirah-02", "no": 21, "nama": "Bilal bin Rabah", "tajuk": "Saidina Bilal bin Rabah RA — Rahsia Tapak Kaki Yang Didengari Di Dalam Syurga", "lokasi": "Fasa Madinah | Amalan Istiqamah Muazzin Rasulullah S.A.W.", "subtema": "Muazzin Nabi", "ibrah": "Konsistensi Amal Kecil (Istiqamah) & Menjaga Wuduk", "sumber": "Sahih Al-Bukhari 1149", "link": "https://sunnah.com/bukhari:1149", "tema": "Akhlak & Adab", "hook": "\"Wahai Bilal! Ceritakanlah kepadaku apakah amalan paling diharapkan yang telah engkau lakukan di dalam Islam? Kerana sesungguhnya aku telah mendengar bunyi derapan tapak kasutmu berjalan di hadapanku di dalam Syurga!\"", "body": ["Bayangkan betapa terkejut dan bahagianya seorang bekas hamba kulit hitam dari Habsyah yang dahulunya dijemur di atas batu panas Makkah apabila menerima berita gembira itu terus daripada lisan Rasulullah S.A.W. pada waktu Subuh!", "Kisah sahih yang diriwayatkan oleh Abu Hurairah RA di dalam Sahih Al-Bukhari dan Sahih Muslim ini membuka rahsia bagaimana amalan kecil yang konsisten mampu membawa seseorang ke darjat tertinggi di dalam Syurga.", "Apabila ditanya oleh Rasulullah S.A.W. pada pagi tersebut, adakah Saidina Bilal bin Rabah RA menyebut amalan yang luar biasa sukar?", "Perhatikan jawapan rendah diri Bilal RA di dalam Sahih Al-Bukhari:", "\"Wahai Rasulullah, aku tidak pernah melakukan sesuatu amalan pun yang aku rasakan lebih aku harapkan pahalanya di sisiiku melainkan setiap kali aku mengambil wuduk (bersuci) pada waktu siang ataupun malam, aku pasti akan mendirikan solat sunat dengan wuduk tersebut sebanyak mana yang ditakdirkan untukku bersolat!\"", "Dalam riwayat Jami' At-Tirmidhi, Bilal RA menambah bahawa setiap kali beliau selesai melaungkan azan, beliau akan mendirikan solat sunat dua rakaat, dan setiap kali wuduknya terbatal, beliau segera memperbaharui wuduknya semula lalu bersolat dua rakaat!", "Mendengar jawapan itu, Rasulullah S.A.W. bersabda:", "\"Dengan sebab dua amalan itulah (engkau mencapai kedudukan tersebut di dalam Syurga)!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Kuasa Istiqamah Dalam Amalan Kecil: Kita tidak semestinya melakukan perkara yang terlalu besar sekali-sekala untuk berjaya; amalan ringan seperti menjaga wuduk dan solat sunat dua rakaat yang dilakukan secara berterusan tanpa putus mempunyai impak luar biasa.", "Islam Mengangkat Kemuliaan Melalui Taqwa, Bukan Keturunan: Bilal bin Rabah RA yang dahulunya seorang hamba yang ditindas diangkat menjadi Muazzin Rasulullah S.A.W. dan penghuni Syurga kerana ketulusan imannya.", "Jadikan Setiap Kebersihan Fizikal Pintu Kepada Ibadah: Menjaga wuduk sepanjang hari bukan sahaja menyucikan anggota badan, malah menjadi perisai rohani yang menghubungkan hati kita dengan solat.", "Mampukah kita memulakan tabiat kecil hari ini — setiap kali selesai mengambil wuduk, kita hadiahkan dua rakaat solat sunat wuduk secara konsisten seperti Bilal bin Rabah RA?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1052, "siri": "Sirah-02", "no": 22, "nama": "Bilal bin Rabah", "tajuk": "Saidina Bilal bin Rabah RA — Menahan Lapar 30 Hari Hanya Dengan Bekalan Di Bawah Ketiak", "lokasi": "Fasa Awal Perjuangan Islam | Makkah & Madinah", "subtema": "Muazzin Nabi", "ibrah": "Ketabahan Menghadapi Kesempitan Ekonomi Demi Iman", "sumber": "Jami' At-Tirmidhi 2472", "link": "https://sunnah.com/tirmidhi:2472", "tema": "Sabar & Tawakal", "hook": "\"Telah berlalu ke atasku tiga puluh hari dan tiga puluh malam, sedangkan tiada sebarang makanan pun pada diriku dan pada Bilal yang boleh dimakan oleh makhluk bernyawa melainkan sedikit bekalan yang dapat disembunyikan di bawah ketiak Bilal!\"", "body": ["Sabda Rasulullah S.A.W. yang diriwayatkan oleh Anas bin Malik RA di dalam Jami' At-Tirmidhi ini menyedarkan kita betapa getirnya penderitaan dan kelaparan yang ditempuh oleh Baginda S.A.W. serta Saidina Bilal bin Rabah RA demi menyampaikan Islam kepada kita.", "Kita hari ini sering mengeluh apabila perniagaan sedikit perlahan, gaji lewat masuk sehari dua, atau hidangan makanan kurang menepati selera.", "Tetapi dengarlah pengakuan Rasulullah S.A.W. sendiri di dalam hadis sahih ini:", "\"Sesungguhnya aku telah diancam dan ditakut-takutkan kerana jalan Allah pada tahap yang tiada seorang pun pernah diancam sedemikian rupa! Dan sesungguhnya aku telah disakiti kerana jalan Allah pada tahap yang tiada seorang pun pernah disakiti sedemikian rupa!\"", "Baginda S.A.W. kemudian menceritakan bagaimana selama sebulan penuh (30 hari dan 30 malam), Baginda bersama pembantu setianya, Bilal bin Rabah RA berdepan kesempitan bekalan makanan yang amat kritikal.", "Jumlah makanan yang ada untuk mereka berdua bertahan hidup sepanjang tempoh itu hanyalah sebesar bungkusan kecil yang muat dikepit di bawah ketiak Bilal RA!", "Namun dalam keadaan perut yang begitu lapar dan diancam musuh dari segenap penjuru, Bilal bin Rabah RA tidak pernah meninggalkan Rasulullah S.A.W. walau sesaat, dan Rasulullah S.A.W. pula tidak pernah berputus asa meneruskan misi dakwahnya.", "3 Pengajaran (Ibrah) Untuk Kita:", "Nikmat Iman Yang Sampai Kepada Kita Dibayar Dengan Pengorbanan Besar: Kemudahan kita beribadah dengan aman pada hari ini adalah hasil ketabahan Rasulullah S.A.W. dan para sahabat menahan lapar serta ancaman selama bertahun-tahun.", "Kesempitan Ekonomi Bukan Alasan Menggadaikan Prinsip: Walaupun sebulan hanya mempunyai sedikit makanan, Bilal RA kekal setia mempertahankan tauhid tanpa tunduk kepada tawaran musuh.", "Didik Hati Untuk Bersyukur Dengan Rezeki Harian: Mengingati kesusahan hidup Rasulullah S.A.W. dan Bilal RA akan memadamkan sifat suka merungut terhadap nikmat makanan yang ada di meja kita hari ini.", "Apabila kita menikmati hidangan yang mencukupi bersama keluarga hari ini, sudahkah kita mengucapkan Alhamdulillah dan berselawat mengenangkan pengorbanan Rasulullah S.A.W.?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1053, "siri": "Sirah-02", "no": 23, "nama": "Khabbab bin Al-Aratt", "tajuk": "Saidina Khabbab bin Al-Aratt RA — Tukang Besi Yang Dibakar Belakangnya & Janji Kemenangan", "lokasi": "Tahun 4 – 6 Kenabian (614 – 616 M) | Fasa Penindasan Di Makkah", "subtema": "As-Sabiqun Al-Awwalun", "ibrah": "Sabar Dalam Proses Perjuangan & Tidak Gesa-Gesa", "sumber": "Sahih Al-Bukhari 3612", "link": "https://sunnah.com/bukhari:3612", "tema": "Sabar & Tawakal", "hook": "Tubuh belakangnya ditekap di atas bara api dan besi panas sehingga lemak daripada belakang badannya sendiri yang memadamkan bara api tersebut, namun imannya tidak goyah walau seinci!", "body": ["Kisah ketabahan luar biasa sahabat As-Sabiqun Al-Awwalun (golongan terawal memeluk Islam), Saidina Khabbab bin Al-Aratt RA ini direkodkan secara sahih di dalam kitab Sahih Al-Bukhari.", "Di Makkah, Khabbab bin Al-Aratt RA merupakan seorang tukang besi dan pembuat pedang yang tidak mempunyai pelindung kabilah.", "Apabila beliau mengisytiharkan keislamannya secara terbuka, kaum musyrikin menyeksanya dengan menggunakan bara api dan besi panas di bengkelnya sendiri untuk memaksa beliau kembali menyembah berhala.", "Kemuncak kepedihan penyeksaan itu mendorong Khabbab RA bersama rakan-rakannya pergi menemui Rasulullah S.A.W. yang ketika itu sedang duduk berbantalkan kain selendang (Burdah) Baginda di bawah bayang-bayang Kaabah.", "Khabbab RA mengadu:", "\"Wahai Rasulullah! Tidakkah engkau mahu memohon pertolongan untuk kami? Tidakkah engkau mahu berdoa kepada Allah untuk menyelamatkan kami?\"", "Mendengar aduan itu, Rasulullah S.A.W. terus bangun duduk dalam keadaan wajah Baginda merah menyala tanda kesungguhan, lalu Baginda memberikan satu jawapan yang membina ketahanan mental para sahabat buat selama-lamanya:", "\"Sesungguhnya dalam kalangan umat sebelum kamu dahulu, ada lelaki beriman yang digali lubang untuknya di dalam tanah, lalu diletakkan gergaji di atas kepalanya sehingga tubuhnya terbelah dua, dan ada yang disikat dagingnya dengan sikat besi sehingga terpisah daripada tulang dan uratnya — namun semua penyeksaan itu langsung tidak memalingkan dia daripada agamanya!\"", "Kemudian Rasulullah S.A.W. melafazkan satu janji masa depan yang pasti:", "\"Demi Allah! Allah pasti akan menyempurnakan urusan agama ini sehinggalah seorang pengembara yang berjalan dari Sana'a ke Hadramaut (di Yaman) tidak akan takut kepada sesiapa pun selain kepada Allah, atau hanya bimbangkan serigala terhadap kambing gembalaannya; akan tetapi kamu semua adalah kaum yang tergesa-gesa!\"", "Dan Khabbab bin Al-Aratt RA dipanjangkan usia oleh Allah sehingga beliau menyaksikan sendiri dengan mata kepalanya bagaimana janji Rasulullah S.A.W. itu menjadi kenyataan!", "3 Pengajaran (Ibrah) Untuk Kita:", "Kejayaan Besar Menuntut Kesabaran Melalui Proses (Jangan Tergesa-Gesa): Setiap perjuangan, pembinaan organisasi, atau perubahan hidup mempunyai fasa ujiannya yang tersendiri sebelum membuahkan hasil kemenangan.", "Visi Jangka Panjang Menguatkan Ketahanan Semasa: Di saat paling gelap ketika ditindas di Makkah, Rasulullah S.A.W. menanamkan visi masa depan yang terang benderang ke dalam minda para sahabat.", "Bandingkan Ujian Kita Dengan Mereka Yang Lebih Berat Diuji: Mengingati ketabahan umat terdahulu menjadikan ujian harian yang kita hadapi terasa jauh lebih ringan dan mampu ditempuhi.", "Adakah kita terlalu cepat berputus asa apabila usaha kita belum menampakkan hasil segera, atau kita terus bersabar yakin dengan janji Allah?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1054, "siri": "Sirah-02", "no": 24, "nama": "Ammar bin Yasir", "tajuk": "Saidina Ammar bin Yasir RA — Memikul Dua Batu Bata Sekali Gus Ketika Membina Masjid", "lokasi": "1 Hijrah (622 M) | Pembinaan Masjid Nabawi, Madinah Al-Munawwarah", "subtema": "Muhajirin", "ibrah": "Bekerja Lebih Daripada Biasa (Extra Mile) & Keteguhan", "sumber": "Sahih Al-Bukhari 2812", "link": "https://sunnah.com/bukhari:2812", "tema": "Akhlak & Adab", "hook": "Ketika semua orang mengangkat seketul batu bata seorang demi seorang di bawah terik matahari untuk membina Masjid Nabawi, lelaki ini memikul dua ketul batu bata sekali gus: satu untuk dirinya, dan satu lagi untuk Rasulullah S.A.W.!", "body": ["Kisah penuh kasih sayang dan kesungguhan Saidina Ammar bin Yasir RA ini diriwayatkan oleh Abu Sa'id Al-Khudri RA di dalam kitab Sahih Al-Bukhari.", "Siapa yang tidak kenal keluarga Yasir?", "Ibu bapa Ammar iaitu Yasir dan Sumayyah RA merupakan syuhada' pertama dalam sejarah Islam yang gugur akibat penyeksaan kejam di Makkah, sehingga Rasulullah S.A.W. bersabda kepada mereka: \"Bersabarlah wahai keluarga Yasir, sesungguhnya tempat kembali yang dijanjikan buat kamu adalah Syurga!\"", "Apabila berhijrah ke Madinah dan tiba masa membina Masjid Nabawi, seluruh sahabat bergotong-royong mengangkat batu bata tanah liat (labin).", "Abu Sa'id Al-Khudri RA menceritakan di dalam Sahih Al-Bukhari:", "\"Semasa membina masjid itu, kami semua membawa batu bata seketul demi seketul, sedangkan Ammar bin Yasir pula membawa dua ketul batu bata sekali gus!\"", "Kerana semangatnya yang begitu berkobar-kobar untuk menyiapkan rumah Allah dan meringankan beban Rasulullah S.A.W., seluruh kepala dan tubuh Ammar RA dipenuhi debu tanah.", "Rasulullah S.A.W. berjalan menghampiri Ammar bin Yasir RA.", "Dengan tangan mulia Baginda sendiri, Rasulullah S.A.W. menyapu dan membersihkan debu-debu tanah yang melekat di kepala dan wajah Ammar RA sambil bersabda dengan penuh belas kasihan:", "\"Kasihan Ammar (Semoga Allah merahmati Ammar)! Dia mengajak mereka kepada Syurga (mentaati Allah), sedangkan mereka mengajaknya kepada Neraka.\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Budaya Kerja Lebih Daripada Biasa (Go The Extra Mile): Orang yang mencintai perjuangannya tidak berkira melakukan kerja dua kali ganda berbanding orang lain demi memastikan matlamat pasukan tercapai.", "Sentuhan Peribadi Pemimpin Menghargai Pekerja: Tindakan Rasulullah S.A.W. menyapu sendiri debu di kepala Ammar RA menunjukkan betapa dekatnya hati seorang pemimpin agung dengan ahli pasukannya yang bekerja keras.", "Trauma Masa Lalu Diubah Menjadi Tenaga Produktif: Walaupun pernah melalui tragedi kehilangan ibu bapa di Makkah, Ammar RA tidak hidup dalam kemurungan, sebaliknya menjadi penyumbang paling aktif membina komuniti baharu di Madinah.", "Dalam melaksanakan tugasan kita hari ini, adakah kita sekadar bekerja cukup makan (\"seketul bata\"), atau kita berusaha memberi nilai tambah terbaik seperti Ammar bin Yasir RA?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1055, "siri": "Sirah-02", "no": 25, "nama": "Salman Al-Farisi", "tajuk": "Saidina Salman Al-Farisi RA — Nasihat Keseimbangan Hidup Yang Diiktiraf Benar Oleh Nabi", "lokasi": "Fasa Madinah | Persaudaraan Salman Al-Farisi RA & Abu Ad-Darda' RA", "subtema": "Muhajirin", "ibrah": "Keseimbangan Ibadah, Kesihatan Badan & Tanggungjawab Keluarga", "sumber": "Sahih Al-Bukhari 1968", "link": "https://sunnah.com/bukhari:1968", "tema": "Akhlak & Adab", "hook": "\"Sesungguhnya Tuhanmu mempunyai hak ke atas dirimu, tubuh badanmu mempunyai hak ke atas dirimu, dan ahli keluargamu juga mempunyai hak ke atas dirimu; maka tunaikanlah hak bagi setiap yang mempunyai hak!\"", "body": ["Kata-kata hikmah yang menjadi prinsip emas pengurusan masa dan keseimbangan hidup (work-life-worship balance) dalam Islam ini diucapkan oleh sahabat agung berasal dari Parsi, Saidina Salman Al-Farisi RA di dalam Sahih Al-Bukhari!", "Rasulullah S.A.W. telah mempersaudarakan Salman Al-Farisi RA dengan sahabat Ansar, Abu Ad-Darda' RA.", "Suatu hari, Salman RA pergi menziarahi rumah saudaranya Abu Ad-Darda' RA dan mendapati isteri Abu Ad-Darda' (Ummu Ad-Darda') berada dalam keadaan pakaian yang tidak terurus.", "Apabila Salman RA bertanya puncanya, Ummu Ad-Darda' menjawab:", "\"Saudaramu Abu Ad-Darda' sudah tidak mempunyai sebarang hajat lagi terhadap urusan dunia (kerana dia berpuasa sepanjang siang dan berjaga solat sepanjang malam tanpa tidur)!\"", "Tidak lama kemudian, Abu Ad-Darda' RA pulang dan menghidangkan makanan buat tetamunya Salman RA sambil berkata, \"Makanlah wahai saudaraku, sesungguhnya aku sedang berpuasa sunat.\"", "Salman RA menjawab dengan tegas: \"Aku bersumpah tidak akan menjamah makanan ini sehinggalah engkau turut berbuka dan makan bersamaku!\"", "Lalu Abu Ad-Darda' RA pun makan bersama Salman RA.", "Apabila tiba awal malam, Abu Ad-Darda' RA bangun mahu memulakan solat malam, namun Salman RA memegang dan menyuruhnya: \"Tidurlah dahulu!\"", "Selepas seketika, Abu Ad-Darda' RA bangun lagi, dan Salman RA berkata lagi: \"Tidurlah dahulu!\"", "Apabila tiba penghujung malam (sepertiga malam terakhir), barulah Salman RA mengejutkan Abu Ad-Darda' RA: \"Sekarang bangunlah!\" lalu mereka berdua mendirikan solat tahajud bersama-sama.", "Selepas selesai solat, Salman RA menyampaikan nasihat emas itu tentang menunaikan hak Allah, hak kesihatan tubuh badan, dan hak isteri serta keluarga secara seimbang.", "Keesokan paginya, apabila Abu Ad-Darda' RA menceritakan keseluruhan kejadian itu kepada Rasulullah S.A.W., Baginda bersabda:", "\"Sesungguhnya Salman telah berkata benar (Sadaqa Salman)!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Islam Menolak Sikap Melampau Sehingga Mengabaikan Keluarga: Beribadah atau bekerja keras sehingga mengabaikan hak pasangan, anak-anak, dan kesihatan tubuh badan sendiri bukanlah ajaran Sunnah Rasulullah S.A.W.", "Tidur Yang Cukup Adalah Hak Tubuh Badan: Salman RA mengajar bahawa memberikan rehat yang cukup kepada badan pada awal malam membolehkan kita bangun beribadah dan bekerja dengan lebih segar pada penghujung malam dan waktu pagi.", "Sahabat Yang Baik Menegur Ketidakseimbangan Hidup Kita: Salman RA tidak membiarkan saudaranya hanyut dalam semangat yang tidak seimbang, sebaliknya membimbingnya secara praktikal selama sehari semalam.", "Adakah jadual harian kita hari ini sudah memberikan hak yang adil kepada Tuhan kita, kesihatan badan kita, dan keluarga di rumah kita?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1056, "siri": "Sirah-02", "no": 26, "nama": "Hudzaifah bin Al-Yaman", "tajuk": "Saidina Hudzaifah bin Al-Yaman RA — Misi Risikan Rahsia Di Malam Ribut Sejuk Ahzab", "lokasi": "Syawal 5 Hijrah (Mac 627 M) | Malam Kemuncak Perang Ahzab (Khandaq)", "subtema": "Pemegang Rahsia Nabi", "ibrah": "Patuh Arahan Strategik (Disiplin SOP) & Kawal Emosi", "sumber": "Sahih Muslim 1788", "link": "https://sunnah.com/muslim:1788", "tema": "Kepimpinan & Keberanian", "hook": "Beliau menyelinap masuk seorang diri ke tengah-tengah perkhemahan musuh di malam yang gelap gelita, malah sempat memasang anak panah tepat ke arah ketua musuh Abu Sufyan — namun beliau menahan jarinya semata-mata kerana teringat satu baris pesanan SOP Rasulullah S.A.W.!", "body": ["Kisah mendebarkan yang lebih hebat daripada mana-mana filem perisikan moden ini diceritakan sendiri oleh pemegang rahsia Rasulullah S.A.W., Saidina Hudzaifah bin Al-Yaman RA di dalam kitab Sahih Muslim.", "Pada malam terakhir Perang Ahzab, ribut taufan dan angin sejuk yang amat dahsyat melanda kawasan parit Madinah sehingga tiada siapa mampu menggerakkan jari kerana kesejukan dan kelaparan.", "Rasulullah S.A.W. memanggil nama Hudzaifah bin Al-Yaman RA lalu memberi arahan khusus:", "\"Wahai Hudzaifah! Pergilah masuk ke dalam perkhemahan kaum musyrikin itu, lihatlah apakah yang sedang mereka lakukan dan bawalah berita mereka kepadaku, dan jangan sesekali engkau melakukan sebarang tindakan yang membangkitkan kemarahan mereka sehingga engkau kembali kepadaku!\"", "Rasulullah S.A.W. menyapu dada Hudzaifah RA sambil berdoa agar Allah menghilangkan rasa sejuk dan takut daripadanya.", "Hudzaifah RA menceritakan di dalam Sahih Muslim bahawa sebaik sahaja beliau melangkah pergi, tubuhnya terasa hangat seolah-olah sedang berjalan di dalam bilik mandi wap (hammam)!", "Dalam kegelapan ribut yang memadamkan unggun api musuh, Hudzaifah RA menyelinap duduk betul-betul di dalam khemah mesyuarat tentera Quraisy.", "Ketika itu, ketua musuh Abu Sufyan sedang memanaskan belakang badannya di hadapan sedikit bara api.", "Hudzaifah RA mengeluarkan sebatang anak panah putih dan meletakkannya pada tali busur untuk memanah Abu Sufyan dari jarak dekat — satu panahan yang pasti menamatkan riwayat ketua musuh!", "Namun pada saat genting itu, Hudzaifah RA teringat semula arahan tegas Rasulullah S.A.W.: \"Jangan sesekali engkau melakukan apa-apa tindakan ke atas mereka!\"", "Beliau terus menurunkan busurnya dan menyimpan semula anak panah itu!", "Tidak lama kemudian, Abu Sufyan menyedari kemungkinan ada perisik lalu menjerit: \"Hendaklah setiap seorang daripada kamu memegang tangan orang di sebelahnya dan bertanya siapakah namanya!\"", "Dengan kepintaran luar biasa, sebelum orang di sebelahnya sempat bertanya, Hudzaifah RA terlebih dahulu menyambar tangan lelaki di sebelahnya sambil bertanya tegas: \"Siapakah engkau?!\" sehingga lelaki itu menjawab namanya dan Hudzaifah RA terselamat!", "Beliau kembali membawa berita pengunduran musuh kepada Rasulullah S.A.W., lalu Baginda menyelimutkan Hudzaifah RA dengan kain selimut solat Baginda sendiri sehingga pagi!", "3 Pengajaran (Ibrah) Untuk Kita:", "Kepatuhan Mutlak Kepada Arahan Strategik (Disiplin SOP): Walaupun mempunyai peluang keemasan menumbangkan Abu Sufyan, Hudzaifah RA mengawal emosinya kerana beliau faham melanggar arahan ketua boleh menggagalkan keseluruhan misi risikan.", "Kepintaran Berfikir Pantas Ketika Saat Cemas: Tindakan proaktif Hudzaifah RA memegang tangan musuh di sebelahnya terlebih dahulu menyelamatkan nyawanya daripada terbongkar.", "Bantuan Allah Hadir Apabila Kita Taat Tanpa Alasan: Walaupun menggigil kesejukan pada awalnya, ketaatan Hudzaifah RA menyahut panggilan Rasulullah S.A.W. dikurniakan ketenangan dan kehangatan luar biasa oleh Allah.", "Dalam bekerja di bawah satu pasukan atau organisasi, adakah kita patuh kepada strategi besar yang telah ditetapkan atau mudah bertindak mengikut emosi sendiri?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1057, "siri": "Sirah-02", "no": 27, "nama": "Ja'far bin Abi Talib", "tajuk": "Saidina Ja'far bin Abi Talib RA — Memeluk Panji Mu'tah Sehingga Digantikan Dua Sayap Di Syurga", "lokasi": "Jumadal Ula 8 Hijrah (September 629 M) | Medan Perang Mu'tah, Selatan Jordan", "subtema": "Panglima Mu'tah", "ibrah": "Mempertahankan Amanah Hingga Akhir & Ganjaran Syurga", "sumber": "Sahih Al-Bukhari 4260", "link": "https://sunnah.com/bukhari:4260", "tema": "Kepimpinan & Keberanian", "hook": "Pada bahagian hadapan jasadnya terdapat lebih 50 liang luka tikaman tombak dan tetakan pedang tanpa satu pun luka di bahagian belakang, dan kedua-dua tangannya yang terputus kerana memeluk panji Islam telah digantikan oleh Allah dengan dua sayap di dalam Syurga!", "body": ["Kisah kepahlawanan luar biasa sepupu Rasulullah S.A.W., Saidina Ja'far bin Abi Talib RA (Ja'far At-Tayyar) ini dirakamkan secara sahih di dalam kitab Sahih Al-Bukhari.", "Dalam Perang Mu'tah, seramai 3,000 tentera Islam berdepan dengan ketumbukan raksasa 200,000 tentera Empayar Rom Byzantine dan sekutu Arab mereka.", "Rasulullah S.A.W. yang berada jauh di Madinah sedang duduk di atas mimbar sambil mengalirkan air mata, menceritakan detik demi detik pertempuran di Mu'tah secara langsung melalui wahyu Allah kepada para sahabat di Masjid Nabawi!", "Baginda S.A.W. bersabda di dalam Sahih Al-Bukhari:", "\"Panji perang telah diambil oleh Zaid bin Harithah, lalu dia berjuang sehingga gugur syahid. Kemudian panji itu diambil oleh Ja'far bin Abi Talib, lalu dia berjuang sehingga gugur syahid...\"", "Di medan Mu'tah, apabila Ja'far bin Abi Talib RA dikepung rapat oleh tentera Rom, beliau memegang panji Islam dengan tangan kanannya.", "Musuh menebas tangan kanannya sehingga putus, lalu Ja'far RA segera menyambut panji itu dengan tangan kirinya supaya panji Islam tidak jatuh ke tanah!", "Apabila musuh menebas pula tangan kirinya sehingga putus, Ja'far RA memeluk dan mengepit batang panji itu dengan kedua-dua pangkal lengannya rapat ke dadanya sehinggalah beliau gugur syahid!", "Abdullah bin Umar RA yang berada di medan Mu'tah pada hari itu bersaksi di dalam Sahih Al-Bukhari:", "\"Aku berdiri di sisi jenazah Ja'far yang telah syahid pada hari itu, lalu aku mengira pada tubuhnya terdapat 50 liang luka antara tikaman dan tetakan, dan tiada satu pun daripada luka itu berada di bahagian belakang badannya!\"", "Sebagai ganjaran atas pengorbanan kedua-dua tangannya itu, Allah SWT menggantikannya dengan sepasang sayap yang membolehkan Ja'far RA terbang bebas bersama para malaikat di dalam Syurga, sehingga setiap kali Saidina Umar bin Al-Khattab RA bertemu anak Ja'far, beliau memberi salam: \"Assalamu 'alaika wahai putera pemilik dua sayap (Ibnu Dzil-Janahain)!\"", "3 Pengajaran (Ibrah) Untuk Kita:", "Jangan Pernah Berpaling Lari Daripada Tanggungjawab: Ketiadaan walau satu luka pun di bahagian belakang tubuh Ja'far RA membuktikan bahawa beliau menghadap cabaran secara berdepan tanpa pernah berundur walau setapak.", "Pegang Amanah Dengan Segala Keupayaan Yang Ada: Apabila satu jalan tertutup (tangan kanan terputus), Ja'far RA menggunakan tangan kiri, dan apabila kedua-duanya tiada, beliau menggunakan pangkal lengannya demi menjaga panji amanah.", "Setiap Kehilangan Di Jalan Allah Diganti Dengan Yang Lebih Agung: Kehilangan dua tangan yang fana di dunia dibalas oleh Allah dengan dua sayap kemuliaan yang kekal abadi di dalam Syurga.", "Apabila kita diuji dengan kehilangan atau halangan dalam melaksanakan amanah, adakah kita terus mencari jalan mempertahankannya sehingga ke akhir?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1058, "siri": "Sirah-02", "no": 28, "nama": "Khalid bin Al-Walid", "tajuk": "Saidina Khalid bin Al-Walid RA — Sembilan Bilah Pedang Patah Di Tangan Saifullah", "lokasi": "Jumadal Ula 8 Hijrah (September 629 M) | Medan Perang Mu'tah, Selatan Jordan", "subtema": "Saifullah", "ibrah": "Kepintaran Taktikal Waktu Krisis & Keberanian", "sumber": "Sahih Al-Bukhari 4265", "link": "https://sunnah.com/bukhari:4265", "tema": "Kepimpinan & Keberanian", "hook": "\"Telah patah di tanganku pada hari Perang Mu'tah sebanyak sembilan bilah pedang, dan tidak tinggal di tanganku melainkan sebilah pedang lebar buatan Yaman!\"", "body": ["Pengakuan luar biasa ini keluar sendiri daripada lisan panglima perang paling genius dalam sejarah ketenteraan Islam, Saidina Khalid bin Al-Walid RA di dalam kitab Sahih Al-Bukhari!", "Bayangkan situasi paling kritikal dalam Perang Mu'tah itu.", "Ketiga-tiga panglima utama yang dilantik oleh Rasulullah S.A.W. — Zaid bin Harithah RA, Ja'far bin Abi Talib RA, dan Abdullah bin Rawahah RA — telah gugur syahid seorang demi seorang di hadapan 200,000 tentera Rom.", "Barisan tentera Islam yang hanya berjumlah 3,000 orang berada di ambang kehancuran total!", "Pada saat genting itu, para sahabat menyerahkan panji pimpinan kepada Khalid bin Al-Walid RA yang baru sahaja memeluk Islam beberapa bulan sebelumnya.", "Dari atas mimbar Masjid Nabawi di Madinah, Rasulullah S.A.W. mengumumkan pelantikan itu dengan satu gelaran abadi di dalam Sahih Al-Bukhari:", "\"Kemudian panji itu telah diambil oleh sebilah Pedang daripada pedang-pedang Allah (Saifun min Suyufillah), lalu Allah membuka jalan kemenangan (dan keselamatan) buat mereka!\"", "Bagaimanakah Khalid bin Al-Walid RA menyelamatkan 3,000 tentera Islam daripada dikepung 200,000 tentera musuh?", "Pada siang hari itu, Khalid RA bertempur di barisan paling hadapan menahan asakan musuh dengan begitu dahsyat sehingga sembilan bilah pedang besi patah berkecai di tangannya!", "Apabila malam menjelma, Khalid RA menggunakan strategi perang psikologi yang sangat pintar: beliau menukar kedudukan sayap kanan ke sayap kiri, sayap kiri ke kanan, dan mengarahkan pasukan berkuda di belakang membuat bising serta menerbangkan debu tebal pada waktu Subuh!", "Tentera Rom yang melihat panji dan wajah-wajah barisan hadapan yang berbeza pada waktu pagi menyangka bala tentera bantuan yang besar baru sahaja tiba dari Madinah!", "Musuh menjadi gentar dan menghentikan pengejaran, membolehkan Khalid RA membawa pulang tentera Islam ke Madinah dengan selamat!", "3 Pengajaran (Ibrah) Untuk Kita:", "Gabungan Keberanian Fizikal Dan Kepintaran Strategi: Khalid RA bukan sekadar kuat menghayun pedang sehingga patah sembilan bilah, tetapi beliau juga menggunakan akal strategi yang tajam untuk mengelakkan pasukannya daripada musnah.", "Masa Lalu Yang Gelap Tidak Menghalang Seseorang Menjadi Wira: Walaupun Khalid RA pernah menentang tentera Islam sebelum masuk Islam, sebaik sahaja beliau bertaubat dan beriman, kebolehannya diangkat menjadi \"Pedang Allah\".", "Berundur Secara Taktikal Untuk Menyelamatkan Pasukan Adalah Kemenangan: Rasulullah S.A.W. menamakan tindakan bijak Khalid RA menyelamatkan nyawa 3,000 tentera Islam itu sebagai satu kemenangan (Fath), bukan kekalahan.", "Apabila berdepan dengan krisis besar dalam perniagaan atau kerjaya, adakah kita sekadar merempuh secara membabi buta atau menyusun strategi bijak seperti Khalid bin Al-Walid RA?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1059, "siri": "Sirah-02", "no": 29, "nama": "Abdullah bin Mas'ud", "tajuk": "Saidina Abdullah bin Mas'ud RA — Alunan Surah An-Nisa' Yang Mengalirkan Air Mata Nabi", "lokasi": "Fasa Madinah | Kemuliaan Ilmuwan Al-Quran Daripada Kalangan Muhajirin", "subtema": "Ilmuwan Muhajirin", "ibrah": "Menghayati Makna Al-Quran & Rendah Hati Mendengar Ilmu", "sumber": "Sahih Al-Bukhari 4582", "link": "https://sunnah.com/bukhari:4582", "tema": "Ilmu & Dakwah", "hook": "Rasulullah S.A.W. adalah insan yang menerima wahyu Al-Quran daripada Malaikat Jibril, namun pada hari itu Baginda meminta seorang bekas penggembala kambing yang kurus betisnya membacakan Al-Quran untuk Baginda sehingga air mata Baginda mengalir!", "body": ["Kisah benar yang sangat menggetarkan jiwa ini diriwayatkan sendiri oleh Saidina Abdullah bin Mas'ud RA di dalam kitab Sahih Al-Bukhari.", "Abdullah bin Mas'ud RA merupakan seorang sahabat bertubuh kecil yang dahulunya bekerja menggembala kambing di Makkah, namun beliau adalah orang pertama selepas Rasulullah S.A.W. yang berani membaca Al-Quran secara lantang di hadapan pembesar Quraisy di sisi Kaabah sehingga wajahnya dipukul berdarah.", "Pada suatu hari di Madinah, Rasulullah S.A.W. sedang duduk di atas mimbar (atau di majlis bersama beliau), lalu Baginda bersabda kepada Abdullah bin Mas'ud RA:", "\"Wahai Abdullah, bacakanlah Al-Quran untukku!\"", "Dengan penuh rasa segan dan rendah diri, Abdullah bin Mas'ud RA bertanya:", "\"Wahai Rasulullah, patutkah aku yang membacakannya kepada engkau, sedangkan Al-Quran itu diturunkan kepada engkau sendiri?\"", "Rasulullah S.A.W. menjawab dengan satu jawapan yang sangat indah:", "\"Sesungguhnya aku suka untuk mendengar bacaan Al-Quran itu daripada orang lain.\"", "Lalu Abdullah bin Mas'ud RA mula mengalunkan bacaan Surah An-Nisa' dengan suaranya yang merdu dan penuh penghayatan.", "Beliau membaca ayat demi ayat sehinggalah sampai kepada ayat ke-41 Surah An-Nisa':", "\"Maka bagaimanakah halnya nanti apabila Kami datangkan daripada tiap-tiap umat seorang saksi, dan Kami datangkan engkau (wahai Muhammad) sebagai saksi terhadap mereka ini semua?\"", "Tiba-tiba Rasulullah S.A.W. bersabda: \"Cukuplah setakat ini dahulu!\"", "Abdullah bin Mas'ud RA menoleh memandang ke wajah Rasulullah S.A.W., dan alangkah tersentuhnya hati beliau apabila melihat kedua-dua belah mata mulia Baginda S.A.W. sedang bergenang dan mengalirkan air mata yang laju!", "3 Pengajaran (Ibrah) Untuk Kita:", "Tawaduk Seorang Pemimpin Untuk Mendengar Daripada Anak Murid: Walaupun Rasulullah S.A.W. adalah guru paling agung, Baginda tetap suka mendengar bacaan Al-Quran daripada sahabatnya untuk menghayati makna ayat dengan lebih mendalam.", "Membaca Al-Quran Adalah Untuk Ditadabbur, Bukan Sekadar Laju: Air mata Rasulullah S.A.W. mengalir pada ayat ke-41 Surah An-Nisa' kerana Baginda merenung beratnya tanggungjawab menjadi saksi ke atas seluruh umat manusia di Mahsyar kelak.", "Ilmu Mengangkat Insan Kerdil Menjadi Mulia: Apabila para sahabat pernah ketawa melihat betis Abdullah bin Mas'ud RA yang kecil ketika memanjat pokok, Rasulullah S.A.W. menegaskan bahawa kedua-dua betis Ibn Mas'ud itu lebih berat timbangannya di sisi Allah pada Hari Kiamat daripada Gunung Uhud!", "Apabila kita membaca atau mendengar Al-Quran hari ini, adakah hati kita turut berhenti merenung makna ayat-ayatnya sehingga melahirkan rasa insaf?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]},
{"id": 1060, "siri": "Sirah-02", "no": 30, "nama": "Abu Hurairah RA", "tajuk": "Saidina Abu Hurairah RA — Pengsan Kelaparan Di Masjid & Mukjizat Semangkuk Susu", "lokasi": "7 – 10 Hijrah (628 – 632 M) | Kehidupan Ahlus Suffah Di Masjid Nabawi", "subtema": "Perawi Hadis Agung", "ibrah": "Kesabaran Menuntut Ilmu, Ketaatan & Keberkatan Berkongsi", "sumber": "Sahih Al-Bukhari 6452", "link": "https://sunnah.com/bukhari:6452", "tema": "Sabar & Tawakal", "hook": "Siapa sangka, sahabat yang paling banyak meriwayatkan ribuan hadis Rasulullah S.A.W. kepada kita hari ini pernah rebah pengsan di antara mimbar dan bilik Nabi S.A.W. kerana terlalu lapar sehingga orang yang lalu-lalang memijak lehernya menyangka beliau gila!", "body": ["Kisah benar yang amat menyayat hati namun berakhir dengan keajaiban ketaatan ini diceritakan sendiri oleh Saidina Abu Hurairah RA di dalam kitab Sahih Al-Bukhari.", "Demi menghafaz setiap patah hadis yang keluar daripada lisan Rasulullah S.A.W., Abu Hurairah RA tinggal bersama golongan fakir miskin Ahlus Suffah di beranda Masjid Nabawi.", "Pada suatu hari, beliau sudah berhari-hari tidak menjamah makanan sehingga terpaksa mengikat batu di perutnya.", "Beliau duduk di tepi jalan keluar masjid, lalu menegur Abu Bakar RA dan kemudian Umar RA dengan bertanyakan satu ayat Al-Quran — niat sebenarnya adalah supaya mereka perasan beliau sedang kelaparan dan mengajaknya makan, namun kedua-duanya hanya menjawab soalan tafsir itu lalu berlalu pergi!", "Tidak lama kemudian, Rasulullah S.A.W. lalu di situ.", "Sebaik sahaja memandang wajah pucat Abu Hurairah RA, Rasulullah S.A.W. terus memahami isi hati dan kelaparannya lalu tersenyum sambil memanggil dengan panggilan manja:", "\"Wahai Aba Hirr! Ikutlah aku!\"", "Di dalam rumah Baginda, terdapat semangkuk susu hadiah daripada seseorang.", "Rasulullah S.A.W. mengarahkan Abu Hurairah RA: \"Wahai Aba Hirr, pergilah panggil kesemua sahabat Ahlus Suffah datang ke mari!\"", "Hati Abu Hurairah RA berdetik cemas: \"Semangkuk kecil susu ini nak diagihkan kepada puluhan orang Ahlus Suffah? Aku yang sedang kelaparan ini pasti tidak akan dapat walau seteguk pun!\"", "Namun kerana prinsip taat kepada perintah Allah dan Rasul-Nya mengatasi segalanya, beliau tetap memanggil kesemua penghuni Suffah datang dan mengedarkan mangkuk susu itu kepada mereka seorang demi seorang.", "Dengan mukjizat yang dikurniakan Allah kepada Rasulullah S.A.W., setiap seorang daripada puluhan sahabat Ahlus Suffah itu minum daripada satu mangkuk susu yang sama sehingga kenyang semuanya!", "Setelah semua orang kenyang, Rasulullah S.A.W. memegang mangkuk itu sambil tersenyum memandang Abu Hurairah RA:", "\"Wahai Aba Hirr, sekarang tinggal aku dan engkau sahaja. Duduklah dan minumlah!\"", "Abu Hurairah RA minum, lalu Baginda berkata lagi: \"Minumlah lagi!\" dan beliau terus minum berkali-kali sehingga beliau berkata:", "\"Demi Tuhan yang mengutuskanmu dengan kebenaran, sudah tiada ruang lagi di dalam perutku untuk susu ini!\"", "Barulah Rasulullah S.A.W. mengambil mangkuk tersebut, memuji Allah, membaca Bismillah, dan meminum baki susu yang terakhir!", "3 Pengajaran (Ibrah) Untuk Kita:", "Ilmu Yang Berkat Menuntut Kesabaran Menghadapi Kesusahan: Ribuan hadis yang kita baca dengan mudah hari ini dikumpulkan oleh Abu Hurairah RA dengan mengorbankan keselesaan hidup dan menahan lapar di Masjid Nabawi.", "Ketaatan Walaupun Bertentangan Dengan Keinginan Sendiri Membawa Keberkatan: Walaupun perutnya hampir pengsan kelaparan, Abu Hurairah RA patuh mendahulukan puluhan sahabat lain terlebih dahulu, dan akhirnya beliau sendiri mendapat bahagian yang paling mengenyangkan.", "Pemimpin Sejati Makan Paling Akhir Selepas Semua Anak Buah Kenyang: Rasulullah S.A.W. memastikan kesemua tetamu Ahlus Suffah dan pembantunya Abu Hurairah RA minum sehingga puas terlebih dahulu sebelum Baginda menjamah baki yang tinggal.", "Adakah kita menghargai khazanah ilmu hadis peninggalan para sahabat dengan mengamalkannya dalam kehidupan seharian kita?", "Allahumma salli 'ala Muhammad wa 'ala ali Muhammad."]}
);
